public U0 InGetStr(U8 *st)
{//Wait for user to type certain str.
  I64 ch,sc;
  U8 buf[256],*st2;
  while (*st) {
    ch=GetKey(&sc,FALSE);
    if (sc.u8[0]!=SC_SHIFT &&
          sc.u8[0]!=SC_ALT &&
          sc.u8[0]!=SC_CTRL) {
      if (ch==*st) {
        '' ch;
        st++;
      } else {
        st2=Char2KeyName(*st);
        StrPrint(buf,"Press the $GREEN$<%s>$FG$ key.",st2);
        Free(st2);
        PopUpOk(buf);
      }
