U0 DirFileDoc(CDoc *doc,CDirEntry *tmpde)
{
  while (tmpde) {
    if (tmpde->attr & RS_ATTR_DIR) {
      tmpde->user_data=DocPrint(doc,"$TR,\"%s\",U=0x%X$",tmpde->name,tmpde);
      DocPrint(doc,"\n$ID,+2$");
      if (tmpde->sub)
        DirFileDoc(doc,tmpde->sub);
