U0 ACSingleFileAdd(U8 *buf)
{
  I64 ch;
  U8 *ptr=buf,*ptr2,*ptr3;
  while (TRUE) {
    while (TRUE) {
      if (ch=*ptr++) {
        if (Bt(char_bmp_alpha_numeric,ch))
          break;
      } else
        return;
    }
    ptr3=ptr;
    ptr2=ptr;
    ptr--;
    while (TRUE) {
      if (ch=*ptr2++) {
        if (Bt(char_bmp_alpha_numeric,ch))
          *ptr3++=ch;
        else if (ch!=CH_CURSOR)
          break;
      } else {
        ptr2--;
        break;
      }
    }
    *ptr3=0;
    ACHashAdd(ptr);
    ptr=ptr2;
  }
}

