#define LK_PLAIN        5
#define LK_PLAIN_FIND   6
#define LK_PLAIN_LINE   7
#define LK_BIBLE_FIND   8
#define LK_DEF          9
#define LK_HELP_INDEX   10
#define LK_ADDR         11
#define LK_DOC          12 //See SpriteEdText()
