Bool GetLink(I64 type,U8 **_tag,U8 **_link,Bool *_pop_up,
        Bool *_quote,U8 **_html_link)
{
  CEdFileLink *e=CAlloc(sizeof(CEdFileLink));
  Bool res=FALSE;
  if (type>=0) {
    e->num=1;
    switch (type) {
      case LK_FILE:
        if (DocForm(e,,,,ctrl_L_footer)) {
          res=TRUE;
          if (!*e->tag)
            *_tag=StrNew(e->file);
          else
            *_tag=StrNew(e->tag);
          *_link=MStrPrint("FI:%s",e->file);
        }
        break;
      case LK_PLAIN:
        if (DocForm(e,,,,ctrl_L_footer)) {
          res=TRUE;
          if (!*e->tag)
            *_tag=StrNew(e->file);
          else
            *_tag=StrNew(e->tag);
          *_link=MStrPrint("PI:%s",e->file);
        }
        break;
      case LK_FILE_ANCHOR:
        if (DocForm(e,"CEdFileAnchorLink",,,ctrl_L_footer)) {
          res=TRUE;
          if (!*e->tag)
            *_tag=StrNew(e->aux);
          else
            *_tag=StrNew(e->tag);
