        }
        break;
      case LK_FILE_FIND:
        if (DocForm(e,"CEdFileFindLink",,,ctrl_L_footer)) {
          res=TRUE;
          if (e->num==1) {
            if (!*e->tag)
              *_tag=StrNew(e->aux);
            else
              *_tag=StrNew(e->tag);
            *_link=MStrPrint("FF:%s,%s",e->file,e->aux);
          } else {
            if (!*e->tag)
              *_tag=StrNew(e->aux);
            else
              *_tag=StrNew(e->tag);
            *_link=MStrPrint("FF:%s,%s:%d",e->file,e->aux,e->num);
          }
        }
        break;
      case LK_PLAIN_FIND:
        if (DocForm(e,"CEdFileFindLink",,,ctrl_L_footer)) {
          res=TRUE;
          if (e->num==1) {
            if (!*e->tag)
              *_tag=StrNew(e->aux);
            else
              *_tag=StrNew(e->tag);
            *_link=MStrPrint("PF:%s,%s",e->file,e->aux);
          } else {
            if (!*e->tag)
              *_tag=StrNew(e->aux);
            else
              *_tag=StrNew(e->tag);
            *_link=MStrPrint("PF:%s,%s:%d",e->file,e->aux,e->num);
          }
        }
        break;
      case LK_FILE_LINE:
        if (DocForm(e,"CEdFileLineLink",,,ctrl_L_footer)) {
          res=TRUE;
          if (!*e->tag)
            *_tag=StrNew(e->file);
          else
            *_tag=StrNew(e->tag);
          *_link=MStrPrint("FL:%s,%d",e->file,e->num);
        }
        break;
      case LK_PLAIN_LINE:
        if (DocForm(e,"CEdFileLineLink",,,ctrl_L_footer)) {
          res=TRUE;
          if (!*e->tag)
            *_tag=StrNew(e->file);
          else
            *_tag=StrNew(e->tag);
          *_link=MStrPrint("PL:%s,%d",e->file,e->num);
        }
        break;
      case LK_MAN_PAGE:
        if (DocForm(e,"CEdManPageLink",,,ctrl_L_footer)) {
          res=TRUE;
          if (!*e->tag)
            *_tag=StrNew(e->aux);
          else
            *_tag=StrNew(e->tag);
          *_link=MStrPrint("MN:%s",e->aux);
        }
        break;
      case LK_PLACE_ANCHOR:
        if (DocForm(e,"CEdPlaceAnchor",,,ctrl_L_footer)) {
          res=TRUE;
          if (!*e->tag) {
            if (e->hide)
              *_tag=StrNew("");
            else
              *_tag=StrNew(e->aux);
          } else
            *_tag=StrNew(e->tag);
          *_link=StrNew(e->aux);
        }
        break;
      case LK_BIBLE_FIND:
        if (DocForm(e,"CEdBibleLink",,,ctrl_L_footer)) {
          res=TRUE;
          if (!*e->tag)
            *_tag=MStrPrint("%Z,%s",e->book,"ST_BIBLE_BOOKS",e->aux);
          else
            *_tag=StrNew(e->tag);
          *_link=MStrPrint("BF:%Z,%s",e->book,"ST_BIBLE_BOOKS",e->aux);
        }
        break;
      case LK_DEF:
        e->num=-1;
        if (DocForm(e,"CEdDefLink",,,ctrl_L_footer)) {
          res=TRUE;
          if (!*e->tag)
            *_tag=StrNew(e->aux);
          else
            *_tag=StrNew(e->tag);
          if (e->num<0)
            *_link=MStrPrint("DN:%s",e->aux);
          else
            *_link=MStrPrint("DN:%s,%d",e->aux,e->num);

        }
        break;
      case LK_HELP_INDEX:
        if (DocForm(e,"CEdManPageLink",,,ctrl_L_footer)) {
          res=TRUE;
          if (!*e->tag)
            *_tag=StrNew(e->aux);
          else
            *_tag=StrNew(e->tag);
          *_link=MStrPrint("HI:%s",e->aux);
        }
        break;
      case LK_ADDR:
        e->num=DFT_ADDR_LINK_BIN_SIZE;
        if (DocForm(e,"CEdAddrLink",,,ctrl_L_footer)) {
          res=TRUE;
          if (e->num==DFT_ADDR_LINK_BIN_SIZE) {
            if (!*e->tag)
              *_tag=StrNew(e->aux);
            else
              *_tag=StrNew(e->tag);
            *_link=MStrPrint("AD:%s",e->aux);
          } else {
            if (!*e->tag)
              *_tag=MStrPrint("%s,%d",e->aux,e->num);
            else
              *_tag=StrNew(e->tag);
            *_link=MStrPrint("AD:%s,%d",e->aux,e->num);
          }
        }
        break;
    }
  }
  if (*e->html_link)
    *_html_link=StrNew(e->html_link);
  else
    *_html_link=NULL;
  if (e->pop_up)
    *_pop_up=TRUE;
  else
    *_pop_up=FALSE;
  if (e->quote)
    *_quote=TRUE;
  else
    *_quote=FALSE;
  Free(e);
  return res;
}

U0 EdInsLink()
{
  U8 *tag=NULL,*link=NULL,*st=NULL,*html_link=NULL,*pop_up_st;
  Bool pop_up=FALSE,quote=FALSE;
  I64 type=PopUpLinkType(TRUE);
  if (type>=0) {
    if (GetLink(type,&tag,&link,&pop_up,&quote,&html_link)) {
      if (pop_up)
        pop_up_st="+PU";
      else
        pop_up_st="";
      switch (type) {
        case LK_PLACE_ANCHOR:
          if (html_link)
            st=MStrPrint("$AN,\"%$Q\",A=\"%$Q\",HTML=\"%$Q\"$",
                  tag,link,html_link);
          else
            st=MStrPrint("$AN,\"%$Q\",A=\"%$Q\"$",tag,link);
          break;
        default:
          if (html_link)
            st=MStrPrint("$LK%s,\"%$Q\",A=\"%$Q\",HTML=\"%$Q\"$",
                  pop_up_st,tag,link,html_link);
          else
            st=MStrPrint("$LK%s,\"%$Q\",A=\"%$Q\"$",pop_up_st,tag,link);
      }
    }
  }
  if (st) {
    if (quote)
      "%$Q",st;
    else
      "%s",st;
  }
  Free(tag);
  Free(link);
  Free(html_link);
  Free(st);
}

