U0 GrBitMapEdTrimToExtents(CDC **_img,I64 *_xx1,I64 *_yy1,
        I64 *_xx2,I64 *_yy2,CColorROPU32 bkcolor)
{
  CDC *img=*_img;
  I64 i,c,
        x1=0,y1=0,x2=img->width-1,y2=img->height-1; //inclusive
  while (y1<y2) {
    for (i=x1;i<=x2;i++) {
      c=GrPeek(img,i,y1);
      if (c!=bkcolor&&c!=TRANSPARENT) goto tr_y2;
    }
    y1++;
  }

  tr_y2:
  while (y1<y2) {
    for (i=x1;i<=x2;i++) {
      c=GrPeek(img,i,y2);
      if (c!=bkcolor&&c!=TRANSPARENT) goto tr_x1;
    }
    y2--;
  }

  tr_x1:
  while (x1<x2) {
    for (i=y1;i<=y2;i++) {
      c=GrPeek(img,x1,i);
      if (c!=bkcolor&&c!=TRANSPARENT) goto tr_x2;
    }
    x1++;
  }

  tr_x2:
  while (x1<x2) {
    for (i=y1;i<=y2;i++) {
      c=GrPeek(img,x2,i);
      if (c!=bkcolor&&c!=TRANSPARENT) goto tr_done;
    }
    x2--;
  }

  tr_done:
  *_img=DCExt(img,x1,y1,x2,y2);
  *_xx1+=x1;                *_yy1+=y1;
  *_xx2+=x2-(img->width-1); *_yy2+=y2-(img->height-1); //not inclusive
  DCDel(img);
}

U0 GrBitMapEdAddOutline(CDC *img,I64 width,
        CColorROPU32 color,CColorROPU32 bkcolor)
{
  I64 i,j,k,c;
  CColorROPU32 old_color;
  CDC *src;
  if (img->width && img->height) {
    old_color=img->color;
    img->color=color;
    while (width-->0) {
      src=DCExt(img,0,0,img->width-1,img->height-1);
      for (i=0;i<img->height;i++)
        for (j=0;j<img->width;j++)
          if (GrPeek(src,j,i)==bkcolor)
            for (k=0;k<8;k++) {
              c=GrPeek(src,j+gr_x_offsets[k],i+gr_y_offsets[k]);
              if (c>=0 && c!=bkcolor) {
                GrPlot(img,j,i);
                break;
              }
            }
      DCDel(src);
    }
    img->color=old_color;
  }
}

U0 GrBitMapEdEtch(CDC *img,I64 width,CColorROPU32 bkcolor)
{
  I64 i,j,k,c;
  CColorROPU32 old_color;
  CDC *src;
  if (img->width && img->height) {
    old_color=img->color;
    img->color=bkcolor;
    while (width-->0) {
      src=DCExt(img,0,0,img->width-1,img->height-1);
      for (i=0;i<img->height;i++)
        for (j=0;j<img->width;j++)
          if (GrPeek(src,j,i)!=bkcolor)
            for (k=0;k<8;k++) {
              c=GrPeek(src,j+gr_x_offsets[k],i+gr_y_offsets[k]);
              if (c<0 || c==bkcolor) {
                GrPlot(img,j,i);
                break;
              }
            }
      DCDel(src);
    }
    img->color=old_color;
  }
}

I64 SpriteBitMapEd(CDoc *,CDocEntry *doc_e,CDC *dc,I64 *_xx1,I64 *_yy1,
        I64 *_xx2,I64 *_yy2,CDC **_img,CColorROPU32 bkcolor)
{
  I64 i,j,mode=SPBM_LINE,color=BLACK,width=1,msg_code,arg1,arg2,x1,y1,x11,y11,
        x22,y22,res,xx1=*_xx1,yy1=*_yy1,xx2=*_xx2,yy2=*_yy2,
        old_de_flags=doc_e->de_flags;
  Bool down=FALSE;
  U8 *st=NULL;
  CEdFileName filename;
  CDC *img=*_img,
        *clip=NULL,*undo=NULL,*dc2;
  SettingsPush; //See SettingsPush

  doc_e->de_flags|=DOCEF_DONT_DRAW;
  goto bm_menu;

  while (TRUE) {
    if (kbd.scan_code&SCF_CTRL)//grab scroll update?
      GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);

    dc->color=ROPF_DITHER+WHITE<<16+BLACK;
    dc->thick=1;
    GrBorder(dc,xx1-1,yy1-1,xx2,yy2);//This is done little bit too often.

    while (msg_code=ScanMsg(&arg1,&arg2,1<<MSG_MS_L_DOWN|1<<MSG_MS_L_UP|
          1<<MSG_MS_R_DOWN|1<<MSG_MS_MOVE|1<<MSG_KEY_DOWN)) {
      switch (msg_code) {
        case MSG_KEY_DOWN:
          switch (arg1) {
            case CH_SHIFT_ESC:
              res=SPE_ABORT;
              goto bm_key_up_done;
            case CH_ESC:
              res=SPE_CONT;
              goto bm_key_up_done;
            case 'c': //eye-dropper
              dc2=DCScrnCapture(FALSE);
              color=GrPeek(dc2,ms.pos.x,ms.pos.y)^15;//Mouse cursor is XORed.
              DCDel(dc2);
              break;
            case 't': //Set to transparent color
              color=TRANSPARENT;
              break;
          }
          break;

        case MSG_MS_R_DOWN:
bm_menu:
          DCFill(dc);
          StrCpy(Fs->task_title,"Sprite BitMap Menu");
          i=PopUpSpriteBitMap(color,width);
          if (i>=0)
            StrCpy(Fs->task_title,DefineSub(i,"ST_SPRITE_BITMAP_MENU"));
          switch (i) {
            case DOCM_CANCEL:
              res=SPE_ABORT;
              goto bm_done;
            case SPBM_EXIT:
              res=SPE_EXIT;
              goto bm_done;
            case SPBM_MAIN_MENU:
              res=SPE_CONT;
              goto bm_done;
            case SPBM_COLOR:
              i=PopUpColor(,,FALSE);
              if (i>=0) color=i;
              goto bm_menu;
            case SPBM_FIND_AND_REPLACE:
              i=PopUpColor("Find Color\n",,FALSE);
              if (i>=0) {
                j=PopUpColor("Replace Color\n",,FALSE);
                if (j>=0) {
                  DCColorChg(img,i,j);
                  GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
                }
              }
              goto bm_menu;
            case SPBM_TRIM_TO_EXTENTS:
              GrBitMapEdTrimToExtents(&img,&xx1,&yy1,&xx2,&yy2,bkcolor);
              GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
              goto bm_menu;
            case SPBM_ADD_OUTLINE:
              i=PopUpRangeI64(1,16,1,"Outline Width\n");
              if (i>=0) {
                GrBitMapEdAddOutline(img,i,color,bkcolor);
                GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
              }
              goto bm_menu;
            case SPBM_ETCH:
              i=PopUpRangeI64(1,16,1,"Etch Width\n");
              if (i>=0) {
                GrBitMapEdEtch(img,i,bkcolor);
                GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
              }
              goto bm_menu;
            case SPBM_SAVE_GR:
              *filename.name=0;
              if (DocForm(&filename) && *filename.name)
                GRWrite(filename.name,img,DCSF_COMPRESSED|DCSF_PALETTE_GET);
              goto bm_menu;
            case SPBM_DITHER_COLOR:
              i=PopUpColorDither;
              if (i>=0) color=i;
              goto bm_menu;
            case SPBM_WIDTH:
              i=PopUpRangeI64(1,16,1,"Thick\n");
              if (i>=0) width=i;
              goto bm_menu;
            case SPBM_UNDO:
              if (undo) {
                DCFill(img,bkcolor);
                img->color=ROP_EQU;
                GrBlot(img,0,0,undo);
                DCDel(undo);
                undo=NULL;
              }
              goto bm_menu;
            case SPBM_PT:
            case SPBM_LINE:
            case SPBM_ARROW:
            case SPBM_RECT:
            case SPBM_CIRCLE:
            case SPBM_FLOOD_FILL:
            case SPBM_FLOOD_FILL_NOT:
            case SPBM_POLYPT:
            case SPBM_POLYLINE:
            case SPBM_COPY:
            case SPBM_DELETE:
            case SPBM_PASTE:
            case SPBM_PASTE_TRANSPARENT:
              mode=i;
              break;
            case SPBM_TEXT:
            case SPBM_TEXT_BOX:
            case SPBM_TEXT_DIAMOND:
              Free(st);
              st=PopUpGetStr("Enter text and press <ESC>.\n");
              if (st && *st)
                mode=i;
              else
                goto bm_menu;
              break;
          }
          DCDel(undo);
          undo=DCExt(img,0,0,img->width-1,img->height-1);
          undo->bkcolor=bkcolor;
          Refresh(2,TRUE);      //Let popup close
          GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
          down=FALSE;
          break;
        case MSG_MS_L_DOWN:
          switch (mode) {
            case SPBM_PT:
              img->color=color;
              img->thick=width;
              GrPlot3(img,arg1-xx1,arg2-yy1,0);
              GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
              break;
            start:
              if (down)
                GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
              x1=arg1; y1=arg2;
              down=TRUE;
              dc->color=color;
              dc->thick=width;
              case SPBM_LINE:
                GrLine3(dc,x1,y1,0,arg1,arg2,0);
                break;
              case SPBM_ARROW:
                GrArrow3(dc,x1,y1,0,arg1,arg2,0);
                break;
              case SPBM_RECT:
                GrRect(dc,x1,y1,1,1);
                break;
              case SPBM_CIRCLE:
                GrCircle3(dc,x1,y1,0,1);
                break;
              case SPBM_COPY:
              case SPBM_DELETE:
                dc->color=ROPF_DITHER+WHITE<<16+BLACK;
                dc->thick=1;
                GrBorder(dc,x1,y1,x1,y1);
                break;
            end:
              break;
            case SPBM_PASTE:
            case SPBM_PASTE_TRANSPARENT:
              if (clip) {
                GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
                if (mode==SPBM_PASTE) {
                  clip->flags|=DCF_NO_TRANSPARENTS;
                  GrBlot(dc,arg1,arg2,clip);
                  clip->flags&=~DCF_NO_TRANSPARENTS;
                } else {
                  dc2=DCCopy(clip);
                  DCColorChg(dc2,bkcolor);
                  GrBlot(dc,arg1,arg2,dc2);
                  DCDel(dc2);
                }
              }
              break;
            case SPBM_TEXT:
              GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
              dc->color=color;
              GrPrint(dc,arg1,arg2,"%s",st);
              break;
            case SPBM_TEXT_BOX:
              GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
              dc->color=color;
              GrTextBox3(dc,arg1,arg2,0,st);
              break;
            case SPBM_TEXT_DIAMOND:
              GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
              dc->color=color;
              GrTextDiamond3(dc,arg1,arg2,0,st);
              break;
            case SPBM_FLOOD_FILL:
              img->color=color;
              GrFloodFill(img,arg1-xx1,arg2-yy1);
              GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
              break;
            case SPBM_FLOOD_FILL_NOT:
              img->color=color;
              GrFloodFill(img,arg1-xx1,arg2-yy1,TRUE);
              GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
              break;
            case SPBM_POLYLINE:
              if (!down) {
                x1=arg1; y1=arg2;
                down=TRUE;
                dc->color=color;
                dc->thick=width;
                GrLine3(dc,x1,y1,0,arg1,arg2,0);
              }
              break;
            case SPBM_POLYPT:
              x1=arg1; y1=arg2;
              down=TRUE;
              img->color=color;
              img->thick=width;
              GrLine3(img,x1-xx1,y1-yy1,0,arg1-xx1,arg2-yy1,0);
              GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
              break;
          }
          break;
        case MSG_MS_MOVE:
          switch (mode) {
            case SPBM_LINE:
            case SPBM_ARROW:
            case SPBM_POLYLINE:
              if (down) {
                GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
                dc->color=color;
                dc->thick=width;
                if (mode==SPBM_ARROW)
                  GrArrow3(dc,x1,y1,0,arg1,arg2,0);
                else
                  GrLine3(dc,x1,y1,0,arg1,arg2,0);
              }
              break;
            case SPBM_RECT:
              if (down) {
                GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
                if (x1<arg1) {
                  x11=x1;
                  x22=arg1;
                } else {
                  x11=arg1;
                  x22=x1;
                }
                if (y1<arg2) {
                  y11=y1;
                  y22=arg2;
                } else {
                  y11=arg2;
                  y22=y1;
                }
                dc->color=color;
                GrRect(dc,x11,y11,x22-x11+1,y22-y11+1);
              }
              break;
            case SPBM_COPY:
            case SPBM_DELETE:
              if (down) {
                GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
                if (x1<arg1) {
                  x11=x1;
                  x22=arg1;
                } else {
                  x11=arg1;
                  x22=x1;
                }
                if (y1<arg2) {
                  y11=y1;
                  y22=arg2;
                } else {
                  y11=arg2;
                  y22=y1;
                }
                dc->color=ROPF_DITHER+WHITE<<16+BLACK;
                dc->thick=1;
                GrBorder(dc,x11,y11,x22,y22);
              }
              break;
            case SPBM_CIRCLE:
              if (down) {
                GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
                dc->color=color;
                dc->thick=width;
                GrCircle3(dc,x1,y1,0,Sqrt(SqrI64(arg1-x1)+SqrI64(arg2-y1)));
              }
              break;
            case SPBM_PASTE:
            case SPBM_PASTE_TRANSPARENT:
              if (clip) {
                GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
                if (mode==SPBM_PASTE) {
                  clip->flags|=DCF_NO_TRANSPARENTS;
                  GrBlot(dc,arg1,arg2,clip);
                  clip->flags&=~DCF_NO_TRANSPARENTS;
                } else {
                  dc2=DCCopy(clip);
                  DCColorChg(dc2,bkcolor);
                  GrBlot(dc,arg1,arg2,dc2);
                  DCDel(dc2);
                }
              }
              break;
            case SPBM_TEXT:
              GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
              dc->color=color;
              GrPrint(dc,arg1,arg2,"%s",st);
              break;
            case SPBM_TEXT_BOX:
              GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
              dc->color=color;
              GrTextBox3(dc,arg1,arg2,0,st);
              break;
            case SPBM_TEXT_DIAMOND:
              GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
              dc->color=color;
              GrTextDiamond3(dc,arg1,arg2,0,st);
              break;
            case SPBM_POLYPT:
              if (down) {
                img->color=color;
                img->thick=width;
                GrLine3(img,x1-xx1,y1-yy1,0,arg1-xx1,arg2-yy1,0);
                GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
                x1=arg1; y1=arg2;
              }
              break;
          }
          break;
        case MSG_MS_L_UP:
          switch (mode) {
            case SPBM_LINE:
            case SPBM_ARROW:
            case SPBM_POLYPT:
            case SPBM_POLYLINE:
              img->color=color;
              img->thick=width;
              if (mode==SPBM_ARROW)
                GrArrow3(img,x1-xx1,y1-yy1,0,arg1-xx1,arg2-yy1,0);
              else
                GrLine3(img,x1-xx1,y1-yy1,0,arg1-xx1,arg2-yy1,0);
              GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
              if (mode==SPBM_POLYLINE) {
                x1=arg1; y1=arg2;
              } else
                down=FALSE;
              break;
            case SPBM_RECT:
              img->color=color;
              if (x1<arg1) {
                x11=x1;
                x22=arg1;
              } else {
                x11=arg1;
                x22=x1;
              }
              if (y1<arg2) {
                y11=y1;
                y22=arg2;
              } else {
                y11=arg2;
                y22=y1;
              }
              GrRect(img,x11-xx1,y11-yy1,x22-x11+1,y22-y11+1);
              down=FALSE;
              GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
              break;
            case SPBM_COPY:
            case SPBM_DELETE:
              if (x1<arg1) {
                x11=x1;
                x22=arg1;
              } else {
                x11=arg1;
                x22=x1;
              }
              if (y1<arg2) {
                y11=y1;
                y22=arg2;
              } else {
                y11=arg2;
                y22=y1;
              }
              DCDel(clip);
              clip=DCExt(img,x11-xx1,y11-yy1,x22-xx1,y22-yy1);
              clip->bkcolor=bkcolor;
              if (mode==SPBM_DELETE) {
                img->color=bkcolor;
                GrRect(img,x11-xx1,y11-yy1,x22-x11+1,y22-y11+1);
              }
              goto bm_menu;
            case SPBM_CIRCLE:
              img->color=color;
              img->thick=width;
              GrCircle3(img,x1-xx1,y1-yy1,0,
                    Sqrt(SqrI64(arg1-x1)+SqrI64(arg2-y1)));
              down=FALSE;
              GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
              break;
            case SPBM_PASTE:
            case SPBM_PASTE_TRANSPARENT:
              if (clip) {
                GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
                if (mode==SPBM_PASTE) {
                  clip->flags|=DCF_NO_TRANSPARENTS;
                  GrBlot(img,arg1-xx1,arg2-yy1,clip);
                  clip->flags&=~DCF_NO_TRANSPARENTS;
                } else {
                  dc2=DCCopy(clip);
                  DCColorChg(dc2,bkcolor);
                  GrBlot(img,arg1-xx1,arg2-yy1,dc2);
                  DCDel(dc2);
                }
                GrBitMapEdPrepPersistentDC(dc,xx1,yy1,img);
              }
              break;
            case SPBM_TEXT:
              img->color=color;
              GrPrint(img,arg1-xx1,arg2-yy1,"%s",st);
              goto bm_menu;
            case SPBM_TEXT_BOX:
              img->color=color;
              GrTextBox3(img,arg1-xx1,arg2-yy1,0,st);
              goto bm_menu;
            case SPBM_TEXT_DIAMOND:
              img->color=color;
              GrTextDiamond3(img,arg1-xx1,arg2-yy1,0,st);
              goto bm_menu;
          }
          break;
      }
    }
    Refresh;
  }
bm_key_up_done:
  GetMsg(,,1<<MSG_KEY_UP);
bm_done:
  DCDel(clip);
  DCDel(undo);
  Free(st);
  DCFill(dc);
  SettingsPop;
  doc_e->de_flags=old_de_flags;
  *_img=img;
  *_xx1=xx1,*_yy1=yy1,*_xx2=xx2,*_yy2=yy2;
  return res;
}
#help_index "Graphics/Sprite;Sprites"

U0 SpriteElem2Code(CDoc *doc,CSprite *tmpg)
{
  U8 buf1[STR_LEN],buf2[STR_LEN];
  I32 *ptr;
  I64 i,j,k,col,width_internal;
  CD3I32 *p;
  CMeshTri *tri;
  if (!doc) doc=DocPut;
  DocPrint(doc,"%Z",tmpg->type&SPG_TYPE_MASK,"ST_SPRITE_ELEM_CODES");
  switch (tmpg->type&SPG_TYPE_MASK) {
    case SPT_COLOR:
      DocPrint(doc,"{%s}",
            Color2Str(buf1,tmpg->c.color));
      break;
    case SPT_DITHER_COLOR:
      DocPrint(doc,"{%s}",
            Color2Str(buf2,ROPF_DITHER|tmpg->d.dither_color.u8[0]|
            tmpg->d.dither_color.u8[1]<<COLORROP_BITS));
      break;
    case SPT_TRANSFORM_ON:
      DocPrint(doc,"{ON}");
      break;
    case SPT_TRANSFORM_OFF:
      DocPrint(doc,"{OFF}");
      break;
    case SPT_LINE:
    case SPT_ARROW:
    case SPT_PLANAR_SYMMETRY:
      DocPrint(doc,"{(%d,%d),(%d,%d)}",tmpg->pp.x1,tmpg->pp.y1,
            tmpg->pp.x2,tmpg->pp.y2);
      break;
    case SPT_RECT:
      DocPrint(doc,"{(%d,%d):(%d,%d)}",tmpg->pp.x1,tmpg->pp.y1,
            tmpg->pp.x2-tmpg->pp.x1,tmpg->pp.y2-tmpg->pp.y1);
      break;
    case SPT_ROTATED_RECT:
      DocPrint(doc,"{(%d,%d):(%d,%d),%0.4f}",tmpg->ppa.x1,tmpg->ppa.y1,
            tmpg->ppa.x2-tmpg->ppa.x1,tmpg->ppa.y2-tmpg->ppa.y1,
            180/ã*Wrap(tmpg->ppa.angle));
      break;
    case SPT_PT:
    case SPT_FLOOD_FILL:
    case SPT_SHIFT:
      DocPrint(doc,"{(%d,%d)}",tmpg->p.x1,tmpg->p.y1);
      break;
    case SPT_FLOOD_FILL_NOT:
      DocPrint(doc,"{(%d,%d),TRUE}",tmpg->p.x1,tmpg->p.y1);
      break;
    case SPT_CIRCLE:
      DocPrint(doc,"{(%d,%d):%d}",tmpg->pr.x1,tmpg->pr.y1,tmpg->pr.radius);
      break;
    case SPT_THICK:
      DocPrint(doc,"{%d}",tmpg->t.thick);
      break;
    case SPT_ELLIPSE:
      DocPrint(doc,"{(%d,%d):(%d,%d),%0.4f}",tmpg->pwha.x1,tmpg->pwha.y1,
            tmpg->pwha.width,tmpg->pwha.height,180/ã*Wrap(tmpg->pwha.angle));
      break;
    case SPT_POLYGON:
      DocPrint(doc,"{%d,(%d,%d):(%d,%d),%0.4f}",tmpg->pwhas.sides,
            tmpg->pwhas.x1,tmpg->pwhas.y1,
            tmpg->pwhas.width,tmpg->pwhas.height,
            180/ã*Wrap(tmpg->pwhas.angle));
      break;
    case SPT_TEXT:
    case SPT_TEXT_BOX:
    case SPT_TEXT_DIAMOND:
      DocPrint(doc,"{(%d,%d),\"%Q\"}",tmpg->ps.x1,tmpg->ps.y1,tmpg->ps.st);
      break;
    case SPT_POLYLINE:
      ptr=&tmpg->nu.u;
      DocPrint(doc,"{");
      for (i=0;i<tmpg->nu.num;i++,ptr+=2) {
        DocPrint(doc,"(%d,%d)",ptr[0],ptr[1]);
        if (i+1<tmpg->nu.num) DocPrint(doc,",");
        if (i&3==3 && i+1<tmpg->nu.num)
          DocPrint(doc,"\n");
      }
      DocPrint(doc,"}");
      break;
    case SPT_BSPLINE2:
    case SPT_BSPLINE3:
    case SPT_BSPLINE2_CLOSED:
    case SPT_BSPLINE3_CLOSED:
      ptr=&tmpg->nu.u;
      DocPrint(doc,"{");
      for (i=0;i<tmpg->nu.num;i++,ptr+=3) {
        DocPrint(doc,"(%d,%d,%d)",ptr[0],ptr[1],ptr[2]);
        if (i+1<tmpg->nu.num) DocPrint(doc,",");
        if (i&3==3 && i+1<tmpg->nu.num)
          DocPrint(doc,"\n");
      }
      if (tmpg->type&SPG_TYPE_MASK==SPT_BSPLINE2||
            tmpg->type&SPG_TYPE_MASK==SPT_BSPLINE3)
        DocPrint(doc,",FALSE}");
      else
        DocPrint(doc,",TRUE}");
      break;
    case SPT_POLYPT:
      DocPrint(doc,"{(%d,%d),",tmpg->npu.x,tmpg->npu.y);
      ptr=&tmpg->npu.u;
      col=16;
      for (i=0;i<tmpg->npu.num;i++) {
        DocPrint(doc,"%d",BFieldExtU32(ptr,i*3,3));
        if (++col>=64 && i+1<tmpg->npu.num) {
          DocPrint(doc,"\n");
          col=0;
        }
      }
      DocPrint(doc,"}");
      break;
    case SPT_BITMAP:
      DocPrint(doc,"{(%d,%d):(%d,%d),\n",tmpg->pwhu.x1,tmpg->pwhu.y1,
            tmpg->pwhu.width,tmpg->pwhu.height);
      width_internal=(tmpg->pwhu.width+7)&~7;
      if (width_internal<80)
        k=width_internal;
      else
        k=64;
      ptr=&tmpg->pwhu.u;
      col=0;
      for (j=0;j<tmpg->pwhu.height;j++)
        for (i=0;i<width_internal;i++,ptr(U8 *)++) {
          if (i>=tmpg->pwhu.width)
            DocPrint(doc,"_");
          else if (*ptr(U8 *)<16)
            DocPrint(doc,"%X",*ptr(U8 *));
          else
            DocPrint(doc,"%c",CH_SHIFT_SPACE);
          if (++col>=k && (i+1<width_internal||j+1<tmpg->pwhu.height)) {
            DocPrint(doc,"\n");
            col=0;
          }
        }
      DocPrint(doc,"}");
      break;
    case SPT_MESH:
      DocPrint(doc,"{FALSE,");
      p=&tmpg->mu.u;
      col=0;
      for (i=0;i<tmpg->mu.vertex_cnt;i++,p++) {
        DocPrint(doc,"(%d,%d,%d)",p->x,p->y,p->z);
        if (i+1<tmpg->mu.vertex_cnt) DocPrint(doc,",");
        if (++col==4) {
          DocPrint(doc,"\t//%d\n",i);
          col=0;
        }
      }
      DocPrint(doc,":");
      tri=p;
      for (i=0;i<tmpg->mu.tri_cnt;i++,tri++) {
        DocPrint(doc,"(%s,%d,%d,%d)",Color2Str(buf1,tri->color),
              tri->nums[0],tri->nums[1],tri->nums[2]);
        if (i+1<tmpg->mu.tri_cnt) DocPrint(doc,",");
        if (++col>=3 && i+1<tmpg->mu.tri_cnt) {
          DocPrint(doc,"\n");
          col=0;
        }
      }
      DocPrint(doc,"}");
      break;
    case SPT_SHIFTABLE_MESH:
      DocPrint(doc,"{TRUE,(%d,%d,%d):",tmpg->pmu.x,tmpg->pmu.y,tmpg->pmu.z);
      p=&tmpg->pmu.u;
      col=1;
      for (i=0;i<tmpg->pmu.vertex_cnt;i++,p++) {
        DocPrint(doc,"(%d,%d,%d)",p->x,p->y,p->z);
        if (i+1<tmpg->pmu.vertex_cnt) DocPrint(doc,",");
        if (++col==4) {
          DocPrint(doc,"\t//%d\n",i);
          col=0;
        }
      }
      DocPrint(doc,":");
      tri=p;
      for (i=0;i<tmpg->pmu.tri_cnt;i++,tri++) {
        DocPrint(doc,"(%s,%d,%d,%d)",Color2Str(buf1,tri->color),
              tri->nums[0],tri->nums[1],tri->nums[2]);
        if (i+1<tmpg->pmu.tri_cnt) DocPrint(doc,",");
        if (++col>=3 && i+1<tmpg->pmu.tri_cnt) {
          DocPrint(doc,"\n");
          col=0;
        }
      }
      DocPrint(doc,"}");
      break;
  }
    DocPrint(doc,";\n");
}

public U0 Sprite2Code(CDoc *doc=NULL,U8 *elems)
{//Sprite to text.
  CSprite *tmpg=elems-offset(CSprite.start);
  while (tmpg->type&SPG_TYPE_MASK) {
    SpriteElem2Code(doc,tmpg);
    tmpg(U8 *)+=SpriteElemSize(tmpg);
  }
}

CSprite *Code2SpriteElem(CCmpCtrl *cc,I64 type)
{
  I64 i,num1,num2,size;
  CSprite *res,g;
  CColorROPU32 color;
  U8 *st,*ptr;
  CQueD3I32 headp,*tmpp,*tmpa1;
  CQueMeshTri headt,*tmpt,*tmpt1;
  CQueVectU8 *tmpv;
  MemSet(&g,0,sizeof(CSprite));
  switch (type) {
    start:
      case SPT_COLOR:
      case SPT_DITHER_COLOR:
        st=LexFirstRem(cc,"}");
        color=Str2ColorU32(st);
        Free(st);
        Lex(cc); //Skip color
        g.c.color=color.c0.color;
        if (color&ROPF_DITHER) {
          g.d.dither_color.u8[1]=color.c1.color;
          g.type=SPT_DITHER_COLOR;
        } else
          g.type=SPT_COLOR;
        break;
      case SPT_TRANSFORM_ON:
      case SPT_TRANSFORM_OFF:
        Lex(cc); //Skip {
        if (LexExpressionI64(cc))
          g.type=SPT_TRANSFORM_ON;
        else
          g.type=SPT_TRANSFORM_OFF;
        break;
      case SPT_LINE:
      case SPT_ARROW:
      case SPT_PLANAR_SYMMETRY:
        Lex(cc); //Skip {
        g.type=type;
        LexD2I32(cc,&g.pp.x1);
        if (cc->token!=',')
          LexExcept(cc,"Expecting ',' at ");
        Lex(cc); //Skip ,
        LexD2I32(cc,&g.pp.x2);
        break;
      case SPT_RECT:
      case SPT_ROTATED_RECT:
        Lex(cc); //Skip {
        LexD2I32(cc,&g.pp.x1);
        if (cc->token!=':')
          LexExcept(cc,"Expecting ':' at ");
        Lex(cc); //Skip :
        LexD2I32(cc,&g.pp.x2);
        g.ppa.x2+=g.pp.x1;
        g.ppa.y2+=g.pp.y1;
        if (cc->token==',') {
          Lex(cc); //Skip ,
          g.ppa.angle=ã/180*LexExpressionF64(cc);
          g.type=SPT_ROTATED_RECT;
        } else
          g.type=SPT_RECT;
        break;
      case SPT_PT:
      case SPT_SHIFT:
        Lex(cc); //Skip {
        g.type=type;
        LexD2I32(cc,&g.p.x1);
        break;
      case SPT_FLOOD_FILL:
      case SPT_FLOOD_FILL_NOT:
        Lex(cc); //Skip {
        LexD2I32(cc,&g.p.x1);
        if (cc->token==',') {
          Lex(cc); //Skip ,
          i=LexExpressionI64(cc);
        } else
          i=0;
        if (i)
          g.type=SPT_FLOOD_FILL_NOT;
        else
          g.type=SPT_FLOOD_FILL;
        break;
      case SPT_THICK:
        Lex(cc); //Skip {
        g.t.thick=LexExpressionI64(cc);
        g.type=SPT_THICK;
        break;
      case SPT_CIRCLE:
        Lex(cc); //Skip {
        g.type=SPT_CIRCLE;
        LexD2I32(cc,&g.pr.x1);
        if (cc->token!=':')
          LexExcept(cc,"Expecting ':' at ");
        Lex(cc); //Skip :
        g.pr.radius=LexExpressionI64(cc);
        break;
      case SPT_POLYGON:
        Lex(cc); //Skip {
        g.pwhas.sides=LexExpressionI64(cc);
        if (cc->token!=',')
          LexExcept(cc,"Expecting ',' at ");
      case SPT_ELLIPSE:
        Lex(cc); //Skip {
        g.type=type;
        LexD2I32(cc,&g.pwha.x1);
        if (cc->token!=':')
          LexExcept(cc,"Expecting ':' at ");
        Lex(cc); //Skip :
        LexD2I32(cc,&g.pwha.width);
        if (cc->token!=',')
          LexExcept(cc,"Expecting ',' at ");
        Lex(cc); //Skip ,
        g.pwha.angle=ã/180*LexExpressionF64(cc);
        break;
    end:
      size=SpriteElemSize(&g)+offset(CSprite.start);
      res=MAlloc(size);
      MemCpy(res,&g,size);
      break;
    case SPT_TEXT:
    case SPT_TEXT_BOX:
    case SPT_TEXT_DIAMOND:
      Lex(cc); //Skip {
      g.type=type;
      LexD2I32(cc,&g.ps.x1);
      if (cc->token!=',')
        LexExcept(cc,"Expecting ',' at ");
      if (Lex(cc)==TK_STR)  //Skip ,
        st=LexExtStr(cc);
      else
        LexExcept(cc,"Expecting string at ");
      size=SpriteElemQuedBaseSize(type);
      i=StrLen(st)+1;
      res=MAlloc(size+i);
      MemCpy(res,&g,size);
      MemCpy(res(U8 *)+size,st,i);
      Free(st);
      break;
    case SPT_POLYLINE:
      Lex(cc); //Skip {
      g.type=SPT_POLYLINE;
      QueInit(&headp);
      while (cc->token=='(') {
        tmpp=CAlloc(sizeof(CQueD3I32));
        LexD2I32(cc,&tmpp->p);
        QueIns(tmpp,headp.last);
        g.nu.num++;
        if (cc->token==',')
          Lex(cc); //Skip ,
      }
      if (g.nu.num<2)
        LexExcept(cc,"Expecting point at ");
      size=SpriteElemQuedBaseSize(SPT_POLYLINE);
      res=MAlloc(size+g.nu.num*sizeof(CD2I32));
      MemCpy(res,&g,size);
      ptr=&res->nu.u;
      tmpp=headp.next;
      while (tmpp!=&headp) {
        tmpa1=tmpp->next;
        MemCpy(ptr,&tmpp->p,sizeof(CD2I32));
        ptr+=sizeof(CD2I32);
        Free(tmpp);
        tmpp=tmpa1;
      }
      break;
    case SPT_BSPLINE2:
    case SPT_BSPLINE3:
    case SPT_BSPLINE2_CLOSED:
    case SPT_BSPLINE3_CLOSED:
      Lex(cc); //Skip {
      QueInit(&headp);
      while (cc->token=='(') {
        tmpp=CAlloc(sizeof(CQueD3I32));
        LexD3I32(cc,&tmpp->p);
        QueIns(tmpp,headp.last);
        g.nu.num++;
        if (cc->token==',')
          Lex(cc); //Skip ,
      }
      if (g.nu.num<2)
        LexExcept(cc,"Expecting point at ");
      size=SpriteElemQuedBaseSize(type);
      res=MAlloc(size+g.nu.num*sizeof(CD3I32));
      if (LexExpressionI64(cc)) {
        if (type==SPT_BSPLINE2||type==SPT_BSPLINE2_CLOSED)
          g.type=SPT_BSPLINE2_CLOSED;
        else
          g.type=SPT_BSPLINE3_CLOSED;
      } else {
        if (type==SPT_BSPLINE2||type==SPT_BSPLINE2_CLOSED)
          g.type=SPT_BSPLINE2;
        else
          g.type=SPT_BSPLINE3;
      }
      MemCpy(res,&g,size);
      ptr=&res->nu.u;
      tmpp=headp.next;
      while (tmpp!=&headp) {
        tmpa1=tmpp->next;
        MemCpy(ptr,&tmpp->p,sizeof(CD3I32));
        ptr+=sizeof(CD3I32);
        Free(tmpp);
        tmpp=tmpa1;
      }
      break;
    case SPT_POLYPT:
      Lex(cc); //Skip {
      LexD2I32(cc,&g.npu.x);
      if (cc->token!=',')
        LexExcept(cc,"Expecting ',' at ");
      tmpv=QueVectU8New;
      while (TRUE) {
        if (!(i=LexGetChar(cc)))
          LexExcept(cc,"Expecting '}' at ");
        if (i=='}')
          break;
        if ('0'<=i<='7')
          QueVectU8Put(tmpv,g.npu.num++,i-'0');
      }
      Bts(&cc->flags,CCf_USE_LAST_U16);
      Lex(cc); //Load '}'
      g.type=SPT_POLYPT;
      size=SpriteElemQuedBaseSize(SPT_POLYPT);
      res=CAlloc(size+(g.npu.num*3+7)>>3);
      MemCpy(res,&g,size);
      ptr=&res->npu.u;
      for (i=0;i<g.npu.num;i++)
        BFieldOrU32(ptr,i*3,QueVectU8Get(tmpv,i));
      QueVectU8Del(tmpv);
      break;
    case SPT_BITMAP:
      Lex(cc); //Skip {
      LexD2I32(cc,&g.pwhu.x1);
      if (cc->token!=':')
        LexExcept(cc,"Expecting ':' at ");
      Lex(cc); //Skip :
      LexD2I32(cc,&g.pwhu.width);
      if (cc->token!=',')
        LexExcept(cc,"Expecting ',' at ");
      tmpv=QueVectU8New;
      num1=0;
      while (TRUE) {
        if (!(i=ToUpper(LexGetChar(cc))))
          LexExcept(cc,"Expecting '}' at ");
        if (i=='}')
          break;
        if ('0'<=i<='9')
          QueVectU8Put(tmpv,num1++,i-'0');
        else if ('A'<=i<='F')
          QueVectU8Put(tmpv,num1++,i-'A'+10);
        else if (i==CH_SPACE||i==CH_SHIFT_SPACE)
          QueVectU8Put(tmpv,num1++,TRANSPARENT);
        else if (i=='_')
          QueVectU8Put(tmpv,num1++,0);
      }
      Bts(&cc->flags,CCf_USE_LAST_U16);
      Lex(cc); //Load '}'
      g.type=SPT_BITMAP;
      size=SpriteElemQuedBaseSize(SPT_BITMAP);
      res=CAlloc(size+num1);
      MemCpy(res,&g,size);
      ptr=&res->pwhu.u;
      for (i=0;i<num1;i++)
        *ptr++=QueVectU8Get(tmpv,i);
      QueVectU8Del(tmpv);
      break;
    case SPT_MESH:
    case SPT_SHIFTABLE_MESH:
      Lex(cc); //Skip {
      if (LexExpressionI64(cc)) {
        g.type=SPT_SHIFTABLE_MESH;
        if (cc->token!=',')
          LexExcept(cc,"Expecting ',' at ");
        Lex(cc); //Skip ,
        LexD3I32(cc,&g.pmu.x);
        if (cc->token!=':')
          LexExcept(cc,"Expecting ':' at ");
        Lex(cc); //Skip :
      } else {
        g.type=SPT_MESH;
        if (cc->token!=',')
          LexExcept(cc,"Expecting ',' at ");
        Lex(cc); //Skip ,
      }
      num1=0;
      QueInit(&headp);
      while (cc->token=='(') {
        tmpp=CAlloc(sizeof(CQueD3I32));
        LexD3I32(cc,&tmpp->p);
        QueIns(tmpp,headp.last);
        num1++;
        if (cc->token==',')
          Lex(cc); //Skip ,
      }
      if (cc->token!=':')
        LexExcept(cc,"Expecting ':' at ");
      Lex(cc); //Skip :
      num2=0;
      QueInit(&headt);
      while (cc->token=='(') {
        tmpt=CAlloc(sizeof(CQueMeshTri));
        st=LexFirstRem(cc,",");
        tmpt->color=Str2ColorU32(st);
        Free(st);
        Lex(cc); //Skip color
        if (cc->token!=',')
          LexExcept(cc,"Expecting ',' at ");
        Lex(cc); //Skip ,
        tmpt->nums[0]=LexExpressionI64(cc);
        if (cc->token!=',')
          LexExcept(cc,"Expecting ',' at ");
        Lex(cc); //Skip ,
        tmpt->nums[1]=LexExpressionI64(cc);
        if (cc->token!=',')
          LexExcept(cc,"Expecting ',' at ");
        Lex(cc); //Skip ,
        tmpt->nums[2]=LexExpressionI64(cc);
        if (cc->token!=')')
          LexExcept(cc,"Expecting ')' at ");
        Lex(cc); //Skip )
        QueIns(tmpt,headt.last);
        num2++;
        if (cc->token==',')
          Lex(cc); //Skip ,
      }
      if (g.type==SPT_MESH) {
        g.mu.vertex_cnt=num1;
        g.mu.tri_cnt=num2;
        size=SpriteElemQuedBaseSize(SPT_MESH);
      } else {
        g.pmu.vertex_cnt=num1;
        g.pmu.tri_cnt=num2;
      }
      size=SpriteElemQuedBaseSize(g.type);
      res=MAlloc(size+num1*sizeof(CD3I32)+num2*sizeof(CMeshTri));
      MemCpy(res,&g,size);
      ptr=res(U8 *)+size;
      tmpp=headp.next;
      while (tmpp!=&headp) {
        tmpa1=tmpp->next;
        MemCpy(ptr,&tmpp->p,sizeof(CD3I32));
        ptr+=sizeof(CD3I32);
        Free(tmpp);
        tmpp=tmpa1;
      }
      tmpt=headt.next;
      while (tmpt!=&headt) {
        tmpt1=tmpt->next;
        MemCpy(ptr,&tmpt->start,sizeof(CMeshTri));
        ptr+=sizeof(CMeshTri);
        Free(tmpt);
        tmpt=tmpt1;
      }
      break;
  }
  if (cc->token!='}')
    LexExcept(cc,"Expecting '}' at ");
  if (Lex(cc)!=';')
    LexExcept(cc,"Expecting ';' at ");
  return res;
}

public U8 *Code2Sprite(CDoc *doc,I64 *_size=NULL)
{//Text to sprite.
  CSprite head;
  U8 *res;
  Bool okay=TRUE,unlock_doc=DocLock(doc);
  CCmpCtrl *cc=CmpCtrlNew(,CCF_DONT_FREE_BUF);
  CHashTable *old_hash_table_lst=cc->htc.hash_table_lst;
  CHashGeneric *tmph;
  I64 i,size=0;
  QueInit(&head);
  LexAttachDoc(cc,,doc);
  try {
    do {
      cc->htc.hash_table_lst=NULL;
      if (Lex(cc)==TK_IDENT && //Skip ;
            (tmph=HashFind(cc->cur_str,gr.sprite_hash,SPHT_ELEM_CODE))) {
        i=tmph->user_data0;
        cc->htc.hash_table_lst=old_hash_table_lst;
        if (Lex(cc)=='{') //Skip ident
          QueIns(Code2SpriteElem(cc,i),head.last);
      } else if (cc->token)
        LexExcept(cc,"Expecting sprite element type name at ");
    } while (cc->token);
    okay=TRUE;
  } catch {
    Fs->catch_except=TRUE;
    okay=FALSE;
  }
  if (unlock_doc)
    DocUnlock(doc);
  if (okay) {
    CmpCtrlDel(cc); //TODO: can crash
    res=SpriteQue2Sprite(&head,&size);
  } else {
    res=NULL;
    size=0;
  }
  if (_size) *_size=size;
  QueDel(&head);
  return res;
}
