        XOR     DI,DI
        REP_MOVSB

        MOV     AX,BOOT_HIGH_LOC_MHD2
        MOV     DS,AX

//My assembler doesn't support 16-bit very well.
        DU8     0xEA;   //JMP BOOT_HIGH_LOC_MHD2:BMHD2_HISTART
        DU16    BMHD2_HISTART-BMHD2_START,BOOT_HIGH_LOC_MHD2;

BMHD2_BOOT_MSG::
