        INT     0x10
        MOV     U8 [BMHD2_PAGE-BMHD2_START],BH //Video page

        MOV     U32 FS:[0],0
@@5:    MOV     SI,BMHD2_BOOT_MSG-BMHD2_START
        CALL    BMHD2_PUTS
