        POP     EDX
        POP     EBX
        POP     ECX
        XOR     EAX,EAX
        POP     GS
        POP     FS
        POP     ES
        POP     DS
        POPFW

//My assembler doesn't support 16-bit very well.
        DU8     0xEA;   //JMP xxxx:yyyy
BMHD2_OLD_CS_RIP:
        DU16    0,0;
BMHD2_END::
