Cd(__DIR__);;
#include "Term"
Cd("..");;
//Anokos terminal.
//A full-screen, black and white text console drawn straight onto the
//VBE linear framebuffer at the display's native resolution.  It
//replaces the TempleOS window manager, wallpaper and DolDoc terminal
//windows.  Commands are TerryC, run by the stock compiler through
//UserTaskCont(); only the screen and the line editor are new.
//
//Note: inside TerryC source, a literal dollar sign is written as two.

#help_index "Anokos/Terminal"

#define TERM_HIST_MAX   64
#define TERM_LINE_MAX   1024
#define TERM_DOLLAR_MAX 512
#define TERM_FPS        30
#define TERM_BLINK      0.5
#define TERM_PRIORITY   0x50000000 //StdOut hook: after input filter, before raw

class CAnoTerm
{
  I64   cols,rows,              //Text grid in chars
        cx,cy,                  //Cursor, cx==cols means wrap is pending
        top,                    //Ring buffer: physical row shown at screen row 0
        lock,
        anchor_x,anchor_y,      //Start of line being edited
        drawn_cy,               //Screen row the cursor was last drawn on
        dollar_len,
        hist_cnt;
  U8    *chars;                 //rows*cols, physical row order
  Bool  *dirty;                 //Per physical row
  U32   *line_buf;              //One scan line of pixels
  U32   fg,bg;
  F64   last_draw,last_blink;
  CTask *task,*pump_task;
  Bool  active,all_dirty,cursor_vis,in_dollar,was_dbg;
  U8    dollar[TERM_DOLLAR_MAX];
  U8    *hist[TERM_HIST_MAX];
};

public CAnoTerm term;

U0 TermLock()
{
  while (LBts(&term.lock,0))
    Yield;
}

U0 TermUnlock()
{
  LBtr(&term.lock,0);
}

I64 TermPhys(I64 y)
{//Screen row to physical row.
  return (term.top+y)%term.rows;
}

U8 *TermCell(I64 x,I64 y)
{
  return term.chars+TermPhys(y)*term.cols+x;
}

U0 TermDirty(I64 y)
{
  if (0<=y<term.rows)
    term.dirty[TermPhys(y)]=TRUE;
}

U0 TermDrawRow(I64 y)
{//Render one text row into the framebuffer.
  I64 x,i,j,k,s=vbe.scale,cw=FONT_WIDTH*vbe.scale,
        row_bytes=term.cols*cw*sizeof(U32);
  U8 *src=term.chars+TermPhys(y)*term.cols,bits,*dst;
  U32 *p,c;
  Bool cur=term.cursor_vis && term.cy==y && term.cx<term.cols;
  for (i=0;i<FONT_HEIGHT;i++) {
    p=term.line_buf;
    for (x=0;x<term.cols;x++) {
      bits=text.font[src[x]].u8[i];
      if (cur && x==term.cx)
        bits=~bits;
      if (!bits) {
        MemSetU32(p,term.bg,cw);
        p+=cw;
      } else if (bits==0xFF) {
        MemSetU32(p,term.fg,cw);
        p+=cw;
      } else
        for (j=0;j<FONT_WIDTH;j++) {
          if (Bt(&bits,j))
            c=term.fg;
          else
            c=term.bg;
          if (s==1)
            *p++=c;
          else {
            MemSetU32(p,c,s);
            p+=s;
          }
        }
    }
    dst=vbe.fb(U8 *)+(y*FONT_HEIGHT*s+i*s)*vbe.pitch;
    for (k=0;k<s;k++) {
      MemCpy(dst,term.line_buf,row_bytes);
      dst+=vbe.pitch;
    }
  }
}

U0 TermRender()
{//Draw rows that changed. Call with lock held.
  I64 y;
  if (term.drawn_cy!=term.cy) {
    TermDirty(term.drawn_cy);
    TermDirty(term.cy);
  }
  for (y=0;y<term.rows;y++)
    if (term.all_dirty || term.dirty[TermPhys(y)]) {
      TermDrawRow(y);
      term.dirty[TermPhys(y)]=FALSE;
    }
  term.all_dirty=FALSE;
  term.drawn_cy=term.cy;
  term.last_draw=tS;
}

U0 TermMaybeRender()
{//Redraw at most TERM_FPS times a second while output is streaming.
//The pump task flushes the rest as soon as the printing task yields.
  if (tS-term.last_draw>1.0/TERM_FPS)
    TermRender;
}

U0 TermClsNoLock()
{
  MemSet(term.chars,CH_SPACE,term.rows*term.cols);
  term.top=0;
  term.cx=term.cy=0;
  term.anchor_x=term.anchor_y=0;
  term.all_dirty=TRUE;
}

public U0 Cls()
{//Clear the Anokos terminal.
  TermLock;
  TermClsNoLock;
  TermRender;
  TermUnlock;
}

U0 TermScroll()
{
  MemSet(term.chars+term.top*term.cols,CH_SPACE,term.cols);
  term.top=(term.top+1)%term.rows;
  term.anchor_y--;
  term.all_dirty=TRUE;
}

U0 TermNewLine()
{
  TermDirty(term.cy);
  term.cx=0;
  if (++term.cy>=term.rows) {
    TermScroll;
    term.cy=term.rows-1;
  }
}

U0 TermRawChar(U8 ch)
{//Put a glyph at the cursor and advance.
  if (term.cx>=term.cols)
    TermNewLine;
  *TermCell(term.cx,term.cy)=ch;
  TermDirty(term.cy);
  term.cx++;
}

U0 TermDollarCmd(U8 *cmd)
{//DolDoc command: show the text of links and text widgets, drop the rest.
  U8 code[3],*ptr;
  if (!*cmd) {
    TermRawChar('$');
    return;
  }
  code[0]=ToUpper(cmd[0]);
  code[1]=ToUpper(cmd[1]);
  code[2]=0;
  if (!StrCmp(code,"CL")) {
    TermClsNoLock;
    return;
  }
  if (LstMatch(code,"TX\0LK\0MA\0MU\0BT\0CB\0LS\0DA\0TR\0CK\0")<0)
    return;
  if (!(ptr=StrFirstOcc(cmd,"\"")))
    return;
  ptr++;
  while (*ptr && *ptr!='"') {
    if (*ptr=='\\' && ptr[1]=='n') {
      TermNewLine;
      ptr+=2;
    } else {
      if (*ptr=='\\' && ptr[1])
        ptr++;
      TermRawChar(*ptr++);
    }
  }
}

U0 TermPutChar(I64 ch)
{//Output one char. Call with lock held.
  ch&=255;
  if (term.in_dollar) {
    if (ch=='$') {
      term.dollar[term.dollar_len]=0;
      term.in_dollar=FALSE;
      TermDollarCmd(term.dollar);
    } else if (term.dollar_len<TERM_DOLLAR_MAX-1)
      term.dollar[term.dollar_len++]=ch;
    return;
  }
  switch (ch) {
    case '$':
      term.in_dollar=TRUE;
      term.dollar_len=0;
      break;
    case '\n':
      TermNewLine;
      break;
    case '\r':
      term.cx=0;
      break;
    case '\t':
      do TermRawChar(CH_SPACE);
      while (term.cx&7 && term.cx<term.cols);
      break;
    case CH_BACKSPACE:
      if (term.cx>0) {
        term.cx--;
        *TermCell(term.cx,term.cy)=CH_SPACE;
        TermDirty(term.cy);
      }
      break;
    default:
      if (ch>=CH_SPACE || Bt(char_bmp_displayable,ch))
        TermRawChar(ch);
  }
}

Bool TermOwnsOutput()
{//Debugger output stays on the raw kernel console.
  return term.active && !IsDbgMode;
}

Bool AnoTermPutKey(I64 ch,I64 sc)
{
  no_warn sc;
  if (!TermOwnsOutput)
    return FALSE;
  if (ch) {
    TermLock;
    TermPutChar(ch);
    TermMaybeRender;
    TermUnlock;
  }
  return TRUE;
}

Bool AnoTermPutS(U8 *st)
{
  if (!TermOwnsOutput)
    return FALSE;
  TermLock;
  while (*st)
    TermPutChar(*st++);
  TermMaybeRender;
  TermUnlock;
  return TRUE;
}

//***** Line editor, used for every GetStr() and the command line *****

U0 TermEditDraw(U8 *buf,I64 len,I64 pos,I64 erase)
{//Redraw the edited line from its anchor. Call with lock held.
  I64 i,x=term.anchor_x,y=term.anchor_y,p;
  for (i=0;i<len+erase;i++) {
    if (x>=term.cols) {
      x=0;
      if (++y>=term.rows) {
        TermScroll;
        y--;
      }
    }
    if (y>=0) {
      if (i<len)
        *TermCell(x,y)=buf[i];
      else
        *TermCell(x,y)=CH_SPACE;
      TermDirty(y);
    }
    x++;
  }
  p=term.anchor_x+pos;
  term.cy=term.anchor_y+p/term.cols;
  term.cx=p%term.cols;
  while (term.cy>=term.rows) {
    TermScroll;
    term.cy--;
  }
  term.cursor_vis=TRUE;
  term.last_blink=tS;
  TermRender;
}

U0 TermHistAdd(U8 *st)
{
  I64 i;
  if (!*st || term.hist_cnt && !StrCmp(term.hist[term.hist_cnt-1],st))
    return;
  if (term.hist_cnt==TERM_HIST_MAX) {
    Free(term.hist[0]);
    for (i=1;i<TERM_HIST_MAX;i++)
      term.hist[i-1]=term.hist[i];
    term.hist_cnt--;
  }
  term.hist[term.hist_cnt++]=StrNew(st,adam_task);
}

U8 *AnoGetStr2(I64 flags=0)
{//Replaces the DolDoc line editor. Returns a MAlloc()ed string.
  U8 buf[TERM_LINE_MAX];
  I64 ch,sc,len=0,pos=0,old_len,hist_i=term.hist_cnt;
  no_warn flags;
  buf[0]=0;
  TermLock;
  if (term.cx>=term.cols)
    TermNewLine;
  term.anchor_x=term.cx;
  term.anchor_y=term.cy;
  TermEditDraw(buf,0,0,0);
  TermUnlock;
  while (TRUE) {
    ch=GetKey(&sc);
    old_len=len;
    switch (sc.u8[0]) {
      case SC_CURSOR_LEFT:
        if (pos>0) pos--;
        goto ge_draw;
      case SC_CURSOR_RIGHT:
        if (pos<len) pos++;
        goto ge_draw;
      case SC_HOME:
        pos=0;
        goto ge_draw;
      case SC_END:
        pos=len;
        goto ge_draw;
      case SC_DELETE:
        if (pos<len) {
          MemCpy(buf+pos,buf+pos+1,len-pos);
          len--;
        }
        goto ge_draw;
      case SC_CURSOR_UP:
        if (hist_i>0) {
          hist_i--;
          StrCpy(buf,term.hist[hist_i]);
          len=pos=StrLen(buf);
        }
        goto ge_draw;
      case SC_CURSOR_DOWN:
        if (hist_i<term.hist_cnt) {
          hist_i++;
          if (hist_i<term.hist_cnt)
            StrCpy(buf,term.hist[hist_i]);
          else
            *buf=0;
          len=pos=StrLen(buf);
        }
        goto ge_draw;
    }
    switch (ch) {
      case '\n':
        TermLock;
        TermEditDraw(buf,len,len,0);
        TermNewLine;
        TermRender;
        TermUnlock;
        TermHistAdd(buf);
        return StrNew(buf);
      case CH_BACKSPACE:
        if (pos>0) {
          MemCpy(buf+pos-1,buf+pos,len-pos+1);
          pos--;
          len--;
        }
        break;
      case CH_ESC:
      case CH_CTRLU:
        len=pos=0;
        *buf=0;
        break;
      case CH_CTRLL:
        TermLock;
        TermClsNoLock;
        TermEditDraw(buf,len,pos,0);
        TermUnlock;
        break;
      case '\t':
        ch=CH_SPACE;
      default:
        if (CH_SPACE<=ch<=0x7E && len<TERM_LINE_MAX-1) {
          MemCpy(buf+pos+1,buf+pos,len-pos+1);
          buf[pos++]=ch;
          len++;
        }
    }
ge_draw:
    TermLock;
    TermEditDraw(buf,len,pos,MaxI64(0,old_len-len));
    TermUnlock;
  }
}

//***** Tasks *****

U0 AnoTermPumpTask(I64)
{//Feeds the keyboard to the focus task, blinks the cursor, flushes output.
  Bool dbg;
  while (TRUE) {
    KbdMsHndlr(FALSE,FALSE);
    if (!TaskValidate(sys_focus_task) && TaskValidate(term.task))
      sys_focus_task=term.task;
    KbdMsgsQue;
    dbg=IsDbgMode;
    if (!dbg) {
      TermLock;
      if (term.was_dbg)
        term.all_dirty=TRUE; //Debugger drew over us
      if (tS-term.last_blink>TERM_BLINK) {
        term.cursor_vis=!term.cursor_vis;
        term.last_blink=tS;
        TermDirty(term.cy);
      }
      TermRender;
      TermUnlock;
    }
    term.was_dbg=dbg;
    Sleep(15);
  }
}

U0 AnoTermTask(I64)
{//The shell: the stock TerryC command line on the Anokos screen.
  Fs->win_inhibit=WIG_USER_TASK_DFT; //Clears WIf_SELF_FOCUS so Ctrl+Alt+C works
  LBts(&Fs->display_flags,DISPLAYf_NOT_RAW);
  sys_focus_task=Fs;
  Cd("~");
  "Anokos (based on TempleOS V%5.3f)\n",sys_os_version;
  "Display %dx%d, %dx%d text. Commands are TerryC, e.g. Dir;\n",
        vbe.width,vbe.height,term.cols,term.rows;
  "Ctrl+Alt+C stops a running command. Cls; clears the screen.\n\n";
  while (TRUE)
    UserTaskCont;
}

U0 AnoNop(I64)
{
}

public U0 AnoTermStart()
{//Take over the screen and start the terminal. Needs a VBE framebuffer.
  if (!Bt(&sys_run_level,RLf_VBE))
    return;
  MemSet(&term,0,sizeof(CAnoTerm)); //JIT globals are not zeroed
  term.cols=vbe.cols;
  term.rows=vbe.rows;
  term.chars=CAlloc(term.cols*term.rows);
  term.dirty=CAlloc(term.rows*sizeof(Bool));
  term.line_buf=CAlloc(vbe.width*sizeof(U32));
  term.fg=0xFFFFFF;
  term.bg=0x000000;
  term.cursor_vis=TRUE;
  TermClsNoLock;
  TermRender;
  term.active=TRUE;
  fp_getstr2=&AnoGetStr2;
  KeyDevAdd(&AnoTermPutKey,&AnoTermPutS,TERM_PRIORITY,FALSE);
  CtrlAltCBSet('T',&AnoNop,"Cmd/(no windows in Anokos)");
  term.pump_task=Spawn(&AnoTermPumpTask,NULL,"Term Pump");
  term.task=Spawn(&AnoTermTask,NULL,"Terminal");
}
U0 BgtAcctsUpdate()
{
  CBgtEntry     *tmpb;
  CBgtTemplate  *tmpt;
  tmpb=b_head.next;
  while (tmpb!=&b_head) {
    if (tmpb->type!=BE_TEMPLATE_COPY) {
      tmpb->credit_idx=StrFileAdd(tmpb->credit,
            &accts_table_strs,accts_table);
      tmpb->debit_idx =StrFileAdd(tmpb->debit,
            &accts_table_strs,accts_table);
    }
    tmpb=tmpb->next;
  }
  tmpt=t_head.next;
  while (tmpt!=&t_head) {
    tmpt->b.credit_idx=StrFileAdd(tmpt->b.credit,
          &accts_table_strs,accts_table);
    tmpt->b.debit_idx =StrFileAdd(tmpt->b.debit,
          &accts_table_strs,accts_table);
    tmpt=tmpt->next;
  }
}

U0 BgtAcctsWrite()
{
  BgtAcctsUpdate;
  StrFileWrite(bgt_accts_file,accts_table,TRUE);
}

U0 BgtAcctsRead()
{
  I64   i,max_num;
  U8    *colors,**s=StrFileRead(bgt_accts_file,&max_num,&colors,TRUE);
  StrFileDel(accts_table);
  accts_table=HashTableNew(512);
  accts_table_strs=0;
  for (i=0;i<=max_num;i++)
    if (s[i])
      StrFileAdd(s[i],&accts_table_strs,accts_table,colors[i]);
  StrFileArrDel(s,max_num);
  Free(colors);
}

I64 BgtAcctColor(U8 *st)
{
  CHashGeneric *tmph;
  if (tmph=HashFind(st,accts_table,SFT_GENERIC))
    return tmph->user_data1;
  else
    return BLACK;
}

U8 *BgtPopUpAcct(U8 *header=NULL,U8 *dft=NULL)
{
  I64 i;
  U8 *res;
  CDoc *doc=DocNew;
  CDocEntry *doc_e,*doc_dft=NULL;
  CHashGeneric *tmph;

  if (header)
    DocPrint(doc,"%s",header);

  for (i=0;i<=accts_table->mask;i++) {
    tmph=accts_table->body[i];
    while (tmph) {
      doc_e=DocPrint(doc,"$FG,%d$$MU-UL,\"%s\",LE=0x%X$\n",
            tmph->user_data1,tmph->str,tmph->str);
      if (dft && !StrCmp(dft,tmph->str))
        doc_dft=doc_e;
      tmph=tmph->next;
    }
  }

  if (doc_dft) {
    doc->cur_entry=doc_dft;
    doc->cur_col=0;
  }
  res=PopUpMenu(doc,DOF_DONT_HOME);
  DocDel(doc);
  return res;
}
U0 BgtEntryDel2(CBgtEntry *tmpb)
{
  if (tmpb->type!=BE_TEMPLATE_COPY) {
    Free(tmpb->credit);
    Free(tmpb->debit);
    Free(tmpb->desc);
  }
}

CBgtEntry *BgtEntryCopy(CBgtEntry *tmpb,Bool periodic_copy)
{
  CBgtEntry *res=MAlloc(sizeof(CBgtEntry));
  MemCpy(res,tmpb,sizeof(CBgtEntry));
  if (periodic_copy) {
    res->credit=StrNew(tmpb->credit);
    res->debit =StrNew(tmpb->debit);
    res->desc  =StrNew(tmpb->desc);
  }
  return res;
}

U0 BgtEntryDel(CBgtEntry *tmpb)
{
  BgtEntryDel2(tmpb);
  Free(tmpb);
}

U0 BgtIns(CBgtEntry *tmpb)
{
  CBgtEntry     *tmpb1=b_head.next;
  while (tmpb1!=&b_head && tmpb1->date<tmpb->date)
    tmpb1=tmpb1->next;
  QueIns(tmpb,tmpb1->last);
}

class CBgtEntryForm
{
  U8    date[512]       format "$DA-P,A=\"Date:%s\"$\n";
  F64   amount          format "Amount$$$DA,A=\"%10.2f\"$\n";
  U8    credit[512]     format "$DA-P,A=\"Credit(from)Acct:%s\"$\n";
  U8    debit [512]     format "$DA-P,A=\"Debit(to)Acct:%s\"$\n";
  U8    desc  [512]     format "$DA-P,A=\"Desc:%s\"$\n";
};

CBgtEntry *BgtEntryPmt(CBgtEntry *dft=NULL)
{
  CBgtEntryForm b;
  CBgtEntry *tmpb;
  U8 *st;
  MemSet(&b,0,sizeof(CBgtEntryForm));
  StrCpy(&b.date,"*");
  if (dft) {
    StrPrint(b.date,"%D",dft->date);
    b.amount=dft->amount;
    StrCpy(b.credit,dft->credit);
    StrCpy(b.debit ,dft->debit);
    StrCpy(b.desc  ,dft->desc);
  }
  while (TRUE)
    if (PopUpForm(&b)) {
      if (!*b.credit) {
        st=BgtPopUpAcct("Credit Acct\n\n");
        if (st!=DOCM_CANCEL)
          StrCpy(b.credit,st);
      } else if (!*b.debit) {
        st=BgtPopUpAcct("Debit Acct\n\n");
        if (st!=DOCM_CANCEL)
          StrCpy(b.debit,st);
      } else {
        tmpb=CAlloc(sizeof(CBgtEntry));
        tmpb->date  =Str2Date(b.date);
        tmpb->amount=b.amount;
        tmpb->credit=StrNew(b.credit);
        tmpb->debit =StrNew(b.debit);
        tmpb->desc  =StrNew(b.desc);
        tmpb->type  =BE_NORMAL;
        StrFileAdd(tmpb->credit,&accts_table_strs,accts_table);
        StrFileAdd(tmpb->debit,&accts_table_strs,accts_table);
        return tmpb;
      }
    } else
      return NULL;
}
U0 BgtDataRead()
{
  CBgtEntry     *tmpb;
  CBgtTemplate  *tmpt;
  I64           i,cnt,size;
  U8            *b,*ptr;
  I64           max_num;
  U8            **s=StrFileRead(bgt_string_file,&max_num);

  MemSet(&b_head,0,sizeof(CBgtEntry));
  QueInit(&b_head);
  b_head.date=Now;
  MemSet(&t_head,0,sizeof(CBgtTemplate));
  QueInit(&t_head);
  t_head.b.date=Now;

  if (ptr=b=FileRead(bgt_data_file,&size)) {
    cnt=*ptr(I64 *)++;
    for (i=0;i<cnt;i++) {
      tmpb=CAlloc(sizeof(CBgtEntry));
      MemCpy(&tmpb->start,ptr,BE_SIZE);
      tmpb->credit=StrNew(s[tmpb->credit_idx]);
      tmpb->debit =StrNew(s[tmpb->debit_idx]);
      tmpb->desc  =StrNew(s[tmpb->desc_idx]);
      QueIns(tmpb,b_head.last);
      ptr+=BE_SIZE;
    }

    cnt=*ptr(I64 *)++;
    for (i=0;i<cnt;i++) {
      tmpt=CAlloc(sizeof(CBgtTemplate));
      MemCpy(&tmpt->start,ptr,BT_SIZE);
      ptr+=BT_SIZE;
      MemCpy(&tmpt->b.start,ptr,BE_SIZE);
      ptr+=BE_SIZE;
      tmpt->b.credit=StrNew(s[tmpt->b.credit_idx]);
      tmpt->b.debit =StrNew(s[tmpt->b.debit_idx]);
      tmpt->b.desc  =StrNew(s[tmpt->b.desc_idx]);
      QueIns(tmpt,t_head.last);
    }
  }

  StrFileArrDel(s,max_num);
  Free(b);

  BgtAcctsUpdate;
}

U0 BgtDataWrite()
{
  I64 i,num=0,size,cnt1,cnt2;
  CHashTable    *table=HashTableNew(1024);
  CBgtEntry     *tmpb;
  CBgtTemplate  *tmpt;
  CHashGeneric *tmph;
  U8 *buf,*ptr;

  for (i=0;i<=accts_table->mask;i++) {
    tmph=accts_table->body[i];
    while (tmph) {
      StrFileAdd(tmph->str,&num,table); //Cosmetics -- make accts appear first.
      tmph=tmph->next;
    }
  }

  tmpb=b_head.next;
  cnt1=0;
  while (tmpb!=&b_head) {
    if (tmpb->type!=BE_TEMPLATE_COPY) {
      tmpb->credit_idx  =StrFileAdd(tmpb->credit,&num,table);
      tmpb->debit_idx   =StrFileAdd(tmpb->debit,&num,table);
      tmpb->desc_idx            =StrFileAdd(tmpb->desc,&num,table);
      cnt1++;
    }
    tmpb=tmpb->next;
  }

  tmpt=t_head.next;
  cnt2=0;
  while (tmpt!=&t_head) {
    tmpt->b.credit_idx  =StrFileAdd(tmpt->b.credit,&num,table);
    tmpt->b.debit_idx   =StrFileAdd(tmpt->b.debit,&num,table);
    tmpt->b.desc_idx            =StrFileAdd(tmpt->b.desc,&num,table);
    cnt2++;
    tmpt=tmpt->next;
  }
  StrFileWrite(bgt_string_file,table);
  StrFileDel(table);

  size=sizeof(I64)*2+cnt1*BE_SIZE+cnt2*(BT_SIZE+BE_SIZE);
  buf=ptr=MAlloc(size);

  MemCpy(ptr,&cnt1,sizeof(I64));
  ptr+=sizeof(I64);
  tmpb=b_head.next;
  while (tmpb!=&b_head) {
    if (tmpb->type!=BE_TEMPLATE_COPY) {
      MemCpy(ptr,&tmpb->start,BE_SIZE);
      ptr+=BE_SIZE;
    }
    tmpb=tmpb->next;
  }

  MemCpy(ptr,&cnt2,sizeof(I64));
  ptr+=sizeof(I64);
  tmpt=t_head.next;
  while (tmpt!=&t_head) {
    MemCpy(ptr,&tmpt->start,BT_SIZE);
    ptr+=BT_SIZE;
    MemCpy(ptr,&tmpt->b.start,BE_SIZE);
    ptr+=BE_SIZE;
    tmpt=tmpt->next;
  }

  FileWrite(bgt_data_file,buf,size);
  Free(buf);
}

U0 BgtDel()
{
  CBgtEntry     *tmpb,*tmpb1;
  CBgtTemplate  *tmpt,*tmpt1;
  tmpb=b_head.next;
  while (tmpb!=&b_head) {
    tmpb1=tmpb->next;
    BgtEntryDel2(tmpb);
    Free(tmpb);
    tmpb=tmpb1;
  }
  tmpt=t_head.next;
  while (tmpt!=&t_head) {
    tmpt1=tmpt->next;
    BgtEntryDel2(&tmpt->b);
    Free(tmpt);
    tmpt=tmpt1;
  }
  StrFileDel(accts_table);
  accts_table=NULL;
  accts_table_strs=0;
}
extern U0 BgtRegen();

Bool BgtPutKey(CDoc *doc,U8 *,I64 ch,I64 sc)
{//ch=ASCII; sc=scan_code
  no_warn sc;
  CBgtEntry *tmpb,*tmpb1;
  CBgtTemplate *tmpt,*tmpt1;
  CDocEntry *doc_ce;
  U8 *st;
  switch (ch) {
    case '\n':
      if ((doc_ce=doc->cur_entry) && doc_ce!=doc &&
            doc_ce->type_u8==DOCT_MENU_VAL) {
        tmpb=doc_ce->user_data;
        if (tmpt=tmpb->template) {
          if (tmpt1=BgtTemplatePmt(tmpt)) {
            QueRem(tmpt);
            BgtTemplatePurge(tmpt);
            BgtEntryDel2(&tmpt->b);
            Free(tmpt);
            QueIns(tmpt1,t_head.last);
            BgtTemplateExpand(tmpt1);
            BgtRegen;
          }
        } else {
          if (tmpb1=BgtEntryPmt(tmpb)) {
            QueRem(tmpb);
            BgtEntryDel(tmpb);
            BgtIns(tmpb1);
            BgtRegen;
          }
        }
      }
      return TRUE;
    case CH_CTRLY:
      if ((doc_ce=doc->cur_entry) && doc_ce!=doc &&
            doc_ce->type_u8==DOCT_MENU_VAL) {
        tmpb=doc_ce->user_data;
        if (tmpt=tmpb->template) {
          QueRem(tmpt);
          BgtTemplateDel(tmpt);
        } else {
          QueRem(tmpb);
          BgtEntryDel(tmpb);
        }
        BgtRegen;
      }
      return TRUE;
    case 'a':
      PopUpOk(  "Set the name and color of your accounts.\n"
            "To delete accounts, manually edit\n"
            "$GREEN$~/Budget/Accts.DD.Z$FG$.");
      if (PopUpEd(bgt_accts_file,Fs)) {
        BgtAcctsRead;
        BgtRegen;
      }
      return TRUE;
    case 'v':
      if ((st=BgtPopUpAcct("View Acct\n\n",view_acct))>=0) {
        StrCpy(view_acct,st);
        BgtRegen;
      }
      return TRUE;
    case 'n':
      if (tmpb1=BgtEntryPmt) {
        BgtIns(tmpb1);
        BgtRegen;
      }
      return TRUE;
    case 't':
      if (tmpt1=BgtTemplatePmt) {
        QueIns(tmpt1,t_head.last);
        BgtTemplateExpand(tmpt1);
        BgtRegen;
      }
      return TRUE;
    case 'c':
      if ((doc_ce=doc->cur_entry) && doc_ce!=doc &&
            doc_ce->type_u8==DOCT_MENU_VAL)
        tmpb=doc_ce->user_data;
      else
        tmpb=NULL;
      if (tmpb1=BgtEntryPmt(tmpb)) {
        BgtIns(tmpb1);
        BgtRegen;
      }
      return TRUE;
    case 'p':
      if ((doc_ce=doc->cur_entry) && doc_ce!=doc &&
            doc_ce->type_u8==DOCT_MENU_VAL) {
        tmpb=doc_ce->user_data;
        if (tmpt1=BgtTemplatePmt(,tmpb)) {
          BgtTemplateExpand(tmpt1,TRUE);
          BgtTemplateDel(tmpt1);
          BgtRegen;
        }
      }
      return TRUE;
  }
  return FALSE;
}

U0 BgtRegen()
{
  I64 timeout_jiffy,c,color=COLOR_INVALID;
  F64 balance=0;
  CDoc *doc,*pdoc,*ddoc;
  CDocEntry *doc_ce;
  CBgtEntry *tmpb=b_head.next,*tmpb_ce;
  doc=DocNew;
  doc->flags|=DOCF_FORM;
  while (tmpb!=&b_head) {
    if (!StrCmp(view_acct,tmpb->credit))
      balance-=tmpb->amount;
    if (!StrCmp(view_acct,tmpb->debit))
      balance+=tmpb->amount;
    c=BgtAcctColor(tmpb->credit);
    if (c!=color) {
      color=c;
      DocPrint(doc,"$FG,%d$",color);
    }
    tmpb->doc_e=DocPrint(doc,
          "$MU-UL,\"%D %8ts %8ts:%8.2f %8.2f:%$Q\",U=0x%X$\n",
          tmpb->date,tmpb->credit,tmpb->debit,balance,
          tmpb->amount,tmpb->desc,tmpb);
    tmpb=tmpb->next;
  }
  DocRecalc(doc);

  if (pdoc=Fs->put_doc) {
    DocLock(pdoc);
//Now, we want to preserve old position in doc, using ugly brute force.
    //It's tricky -- can't use old line num because of editor filters.

    //The price we pay for using the standard document editor is this kludge.
    //When I originally wrote my budget program, I did not have separate budget
    //and line entries, so we never had to resync.

    doc_ce=pdoc->cur_entry;
    timeout_jiffy=cnts.jiffies+JIFFY_FREQ; //Max one second.
    while (doc_ce!=pdoc && cnts.jiffies<timeout_jiffy) {
      while (doc_ce->type_u8!=DOCT_MENU_VAL || !(tmpb_ce=doc_ce->user_data)) {
        doc_ce=doc_ce->next;
        if (doc_ce==pdoc) goto br_cont;
      }
      tmpb=b_head.next;
      while (tmpb!=&b_head) {
        if (tmpb==tmpb_ce) {
          doc->cur_entry=tmpb->doc_e;
          doc->cur_col=0;
          DocCenter(doc);
          goto br_cont;
        }
        tmpb=tmpb->next;
      }
      doc_ce=doc_ce->next;
    }
  }

  br_cont:
  ddoc=Fs->display_doc;
  Fs->put_doc    =doc;
  Fs->display_doc=doc;
  DocDel(pdoc);
  if (pdoc!=ddoc)
    DocDel(ddoc);
  doc->user_put_key=&BgtPutKey;
}

U0 Budget(U8 *dirname="~/Budget")
{
  CDoc *pdoc,*ddoc,*old_put,*old_display;

  Cd(dirname);
  bgt_string_file       =FileNameAbs("Strs.DD.Z");
  bgt_accts_file        =FileNameAbs("Accts.DD.Z");
  bgt_data_file         =FileNameAbs("Bgt.DATA.Z");

  BgtAcctsRead;
  BgtDataRead;
  CBgtTemplatesExpand;
  SettingsPush; //See SettingsPush
  AutoComplete;
  WinBorder;
  WinMax;
  MenuPush(
        "File {"
        "  Abort(,CH_SHIFT_ESC);"
        "  Exit(,CH_ESC);"
        "}"
        "Edit {"
        "  NewEntry(,'n');"
        "  CopyEntry(,'c');"
        "  PeriodicEntry(,'p');"
        "  EditEntry(,'\n');"
        "  DeleteEntry(,CH_CTRLY);"
        "  NewTemplate(,'t');"
        "  AcctsFile(,'a');"
        "}"
        "View {"
        "  ViewAcct(,'v');"
        "}"
        );
  StrCpy(view_acct,"BANK");
  DocMax;
  old_put        =Fs->put_doc;
  old_display    =Fs->display_doc;
  Fs->put_doc    =NULL;
  Fs->display_doc=NULL;
  BgtRegen;
  try
    if (View) {
      BgtDataWrite;
      BgtAcctsWrite;
    }
  catch
    PutExcept;

  pdoc=Fs->put_doc;
  ddoc=Fs->display_doc;
  Fs->put_doc    =old_put;
  Fs->display_doc=old_display;
  DocDel(pdoc);
  if (pdoc!=ddoc)
    DocDel(ddoc);

  SettingsPop;
  BgtDel;
  MenuPop;
}
#define SFT_GENERIC     1

public U8 **StrFileRead(U8 *name,I64 *_max_num=NULL,
        U8 **_colors=NULL,Bool no_nums=FALSE)
{
  CDoc          *doc=DocRead(name,DOCF_DBL_DOLLARS|DOCF_NO_CURSOR);
  CDocEntry     *doc_e=doc->head.next;
  I64           i,max_num=0;
  U8            *ptr,**res,*colors;

  while (doc_e!=doc) {
    if (doc_e->type_u8==DOCT_TEXT) {
      if (no_nums)
        i=++max_num;
      else {
        i=Str2I64(doc_e->tag,,&ptr);
        if (i>max_num) max_num=i;
        if (*ptr==',') ptr++;
        ptr=StrNew(ptr);
        Free(doc_e->tag);
        doc_e->tag=ptr;
      }
      doc_e->user_data=i;
    }
    doc_e=doc_e->next;
  }

  res=CAlloc(sizeof(U8 *)*(max_num+1));
  colors=CAlloc(sizeof(U8)*(max_num+1));
  doc_e=doc->head.next;
  while (doc_e!=doc) {
    if (doc_e->type_u8==DOCT_TEXT && 0<=doc_e->user_data<=max_num) {
      res[doc_e->user_data]=doc_e->tag;
      doc_e->tag=NULL;
      colors[doc_e->user_data]=doc_e->type.u8[1]&15;
    }
    doc_e=doc_e->next;
  }

  DocDel(doc);
  if (_max_num) *_max_num=max_num;
  if (_colors)
    *_colors=colors;
  else
    Free(colors);
  return res;
}

public U0 StrFileArrDel(U8 **a,I64 max_num)
{
  I64 i;
  for (i=0;i<=max_num;i++)
    Free(a[i]);
  Free(a);
}

public I64 StrFileAdd(U8 *st,I64 *_num,
        CHashTable *table,I64 color=COLOR_INVALID)
{
  CHashGeneric *tmph;
  if (!st) return 0;
  if (!(tmph=HashFind(st,table,SFT_GENERIC))) {
    tmph=CAlloc(sizeof(CHashGeneric));
    tmph->type=SFT_GENERIC;
    tmph->str=StrNew(st);
    tmph->user_data0=(*_num)++;
    HashAdd(tmph,table);
  }
  if (color!=COLOR_INVALID)
    tmph->user_data1=color;
  return tmph->user_data0;
}

I64 StrEntriesCompare(CHashGeneric *h1,CHashGeneric *h2)
{
  return h1->user_data0-h2->user_data0;
}

public U0 StrFileWrite(U8 *name,CHashTable *table,Bool no_nums=FALSE)
{
  I64 i,j,cnt,color=BLACK;
  CDoc *doc=DocNew(name);
  CHashGeneric *tmph,**a;
  if (table) {
    cnt=0;      //Count Strings
    for (i=0;i<=table->mask;i++)
      cnt+=LinkedLstCnt(table->body[i]);
    a=MAlloc(cnt*sizeof(CHashGeneric *));
    j=0;        //Load Strings
    for (i=0;i<=table->mask;i++) {
      tmph=table->body[i];
      while (tmph) {
        a[j++]=tmph;
        tmph=tmph->next;
      }
    }
    QSortI64(a,cnt,&StrEntriesCompare);
    for (i=0;i<cnt;i++) {
      tmph=a[i];
      if (tmph->user_data1&15!=color) {
        DocPrint(doc,"$FG,%d$",tmph->user_data1&15);
        color=tmph->user_data1&15;
      }
      if (no_nums)
        DocPrint(doc,"%s\n",tmph->str);
      else
        DocPrint(doc,"%d,%s\n",tmph->user_data0,tmph->str);
    }
    Free(a);
  }
  doc->flags|=DOCF_NO_CURSOR;
  DocWrite(doc);
  DocDel(doc);
}

public U0 StrFileDel(CHashTable *table)
{
  I64 i;
  CHashGeneric *tmph,*tmph1;
  if (!table) return;
  for (i=0;i<=table->mask;i++) {
    tmph=table->body[i];
    while (tmph) {
      tmph1=tmph->next;
      Free(tmph->str);
      Free(tmph);
      tmph=tmph1;
    }
  }
  Free(table->body);
  Free(table);
}
U0 BgtTemplatePurge(CBgtTemplate *tmpt)
{
  CBgtEntry     *tmpb,*tmpb1;
  tmpb=b_head.next;
  while (tmpb!=&b_head) {
    tmpb1=tmpb->next;
    if (tmpb->template==tmpt) {
      QueRem(tmpb);
      BgtEntryDel2(tmpb);
      Free(tmpb);
    }
    tmpb=tmpb1;
  }
}

U0 BgtTemplateDel(CBgtTemplate *tmpt)
{
  BgtTemplatePurge(tmpt);
  BgtEntryDel2(&tmpt->b);
  Free(tmpt);
}

U0 BgtTemplateExpand(CBgtTemplate *tmpt,Bool periodic_copy=FALSE)
{
  CDate         d,start,end;
  CDateStruct   ds;
  CBgtEntry     *tmpb;
  Bool          first=TRUE;

  start=MyStr2Date(tmpt->start_date);
  end  =MyStr2Date(tmpt->end_date);
  tmpt->b.template=tmpt;
  switch (tmpt->type) {
    case BT_INTERVAL:
      d=start;
      while (d<=end) {
        if (!first || !periodic_copy) {
          tmpb=BgtEntryCopy(&tmpt->b,periodic_copy);
          tmpb->date=d;
          if (periodic_copy)
            tmpb->template=NULL;
          else
            tmpb->type=BE_TEMPLATE_COPY;
          BgtIns(tmpb);
        }
        d+=tmpt->period*0x100000000;
        first=FALSE;
      }
      break;
    case BT_MONTHLY:
      Date2Struct(&ds,start);
      while (TRUE) {
        d=Struct2Date(&ds);
        if (d<=end) {
          if (!first || !periodic_copy) {
            tmpb=BgtEntryCopy(&tmpt->b,periodic_copy);
            tmpb->date=d;
            if (periodic_copy)
              tmpb->template=NULL;
            else
              tmpb->type=BE_TEMPLATE_COPY;
            BgtIns(tmpb);
          }
        } else
          break;
        if (++ds.mon>12) {
          ds.mon=1;
          ds.year++;
        }
        first=FALSE;
      }
      break;
    case BT_BIMONTHLY:
      Date2Struct(&ds,start);
      while (TRUE) {
        d=Struct2Date(&ds);
        if (d<=end) {
          if (!first || !periodic_copy) {
            tmpb=BgtEntryCopy(&tmpt->b,periodic_copy);
            tmpb->date=d;
            if (periodic_copy)
              tmpb->template=NULL;
            else
              tmpb->type=BE_TEMPLATE_COPY;
            BgtIns(tmpb);
          }
        } else
          break;
        ds.mon+=2;
        if (ds.mon>12) {
          ds.mon-=12;
          ds.year++;
        }
        first=FALSE;
      }
      break;
    case BT_SEMIANNUAL:
      Date2Struct(&ds,start);
      while (TRUE) {
        d=Struct2Date(&ds);
        if (d<=end) {
          if (!first || !periodic_copy) {
            tmpb=BgtEntryCopy(&tmpt->b,periodic_copy);
            tmpb->date=d;
            if (periodic_copy)
              tmpb->template=NULL;
            else
              tmpb->type=BE_TEMPLATE_COPY;
            BgtIns(tmpb);
          }
        } else
          break;
        ds.mon+=6;
        if (ds.mon>12) {
          ds.mon-=12;
          ds.year++;
        }
        first=FALSE;
      }
      break;
    case BT_ANNUAL:
      Date2Struct(&ds,start);
      while (TRUE) {
        d=Struct2Date(&ds);
        if (d<=end) {
          if (!first || !periodic_copy) {
            tmpb=BgtEntryCopy(&tmpt->b,periodic_copy);
            tmpb->date=d;
            if (periodic_copy)
              tmpb->template=NULL;
            else
              tmpb->type=BE_TEMPLATE_COPY;
            BgtIns(tmpb);
          }
        } else
          break;
        ds.year++;
        first=FALSE;
      }
      break;
  }
}

U0 CBgtTemplatesExpand()
{
  CBgtTemplate  *tmpt=t_head.next;
  while (tmpt!=&t_head) {
    BgtTemplateExpand(tmpt);
    tmpt=tmpt->next;
  }
}

CBgtTemplate *BgtTemplatePmt(CBgtTemplate *dft_t=NULL,CBgtEntry *dft_b=NULL)
{
  CBgtTemplate  t,*tmpt;
  CBgtEntry     *tmpb;
  MemSet(&t,0,sizeof(CBgtTemplate));
  if (dft_t) {
    MemCpy(&t.start,&dft_t->start,BT_SIZE);
    dft_b=&dft_t->b;
  } else {
    t.type=BT_INTERVAL;
    if (dft_b)
      StrPrint(&t.start_date,"%D",dft_b->date);
    else
      StrCpy(&t.start_date,"[");
    StrCpy(&t.end_date,"]");
  }
  while (TRUE)
    if (PopUpForm(&t) && ((t.type==BT_INTERVAL && t.period>0) ||
          t.type>BT_INTERVAL)) {
      if (tmpb=BgtEntryPmt(dft_b)) {
        tmpt=CAlloc(sizeof(CBgtTemplate));
        MemCpy(&tmpt->start,&t.start,BT_SIZE);
        MemCpy(&tmpt->b,tmpb,sizeof(CBgtEntry));
        Free(tmpb);
        return tmpt;
      }
    } else
      break;
  return NULL;
}
