      y=25.0*y;
      if (Rand*(x*x+2.0)*Sqrt(y)<4.0) {
        if (Rand<0.5)
          dc->color=BLUE;
        else
          dc->color=LTBLUE;
      } else
        dc->color=YELLOW;
      if (RandI16<0)
        x=-x;
      x+=150.0*Sin(ã*dt)/(35-y)`1.5;
      GrPlot(dc,X+x,Y-y);
    }
  }
}

