          GrLine3(dc,x1-3*Cos(é),y1-3*Sin(é),0,
                x1-d*Cos(é)+0.5*d*Sin(é),
                y1-d*Sin(é)-0.5*d*Cos(é),0);
          GrLine3(dc,x1-2*d*Cos(é),y1-2*d*Sin(é),0,
