U0 MyDerivative(CMathODE *ode,F64,COrder2D3 *,COrder2D3 *)
{
//The forces due to springs and drag are
  //automatically handled by the
  //ode code.We can add new forces
  //here.
  F64 d,dd;
  CD3 p;
  MyMass *tmpm1,*tmpm2;
  MySpring *tmps;

  tmpm1=ode->next_mass;
  while (tmpm1!=&ode->next_mass) {
    tmpm2=tmpm1->next;
    while (tmpm2!=&ode->next_mass) {
      D3Sub(&p,&tmpm2->state->x,&tmpm1->state->x);
      dd=D3NormSqr(&p);
      if (dd<=Sqr(2*RADIUS)) {
        d=Sqrt(dd)+0.0001;
        dd=10.0*Sqr(Sqr(Sqr(2*RADIUS)-dd));
        D3MulEqu(&p,dd/d);
        D3AddEqu(&tmpm2->DstateDt->DxDt,&p);
        D3SubEqu(&tmpm1->DstateDt->DxDt,&p);
      }
      tmpm2=tmpm2->next;
    }
    tmpm1=tmpm1->next;
  }

  tmps=ode->next_spring;
  while (tmps!=&ode->next_spring) {
    if (main_mode_bttn.state==MMD_PLAY && tmps->type==EMD_THRUSTER &&
          Bt(kbd.down_bitmap,action_scan_codes[tmps->action_key-'0'])) {
      D3Sub(&p,&tmps->end2->state->x,&tmps->end1->state->x);
      D3Unit(&p);
      D3MulEqu(&p,2000);
      D3AddEqu(&tmps->end1->DstateDt->DxDt,&p);
    }
    tmps=tmps->next;
  }
}

MyMass *PlaceMass(I64 x, I64 y)
{
  MyMass *tmpm=CAlloc(sizeof(MyMass));
  tmpm->mass=1.0;
  tmpm->drag_profile_factor=100.0;
  tmpm->x=x;
  tmpm->y=y;
  QueIns(tmpm,ode->last_mass);
  return tmpm;
}

MySpring *PlaceSpring(MyMass *tmpm1,MyMass *tmpm2,I64 type)
{
  MySpring *tmps=CAlloc(sizeof(MySpring));
  F64 d=D3Dist(&tmpm1->x,&tmpm2->x);
  tmps->end1=tmpm1;
  tmps->end2=tmpm2;
  tmps->rest_len=d;
  tmps->type=type;
  if (type==EMD_THRUSTER)
    tmps->const=0;
  else
    tmps->const=2500000/Sqr(d);
  tmps->action_key=next_action_key;
  QueIns(tmps,ode->last_spring);
  return tmps;
}

U0 CenterMasses()
{
  CD3 p;
  MyMass *tmpm1,*tmpm2;
  tmpm1=ode->next_mass;
  if (tmpm1!=&ode->next_mass) {
    D3Copy(&p,&tmpm1->x);
    tmpm2=ode->next_mass;
    while (tmpm2!=&ode->next_mass) {
      D3SubEqu(&tmpm2->x,&p);
      tmpm2=tmpm2->next;
    }
  }
}

U0 NullSprings()
{
  MySpring *tmps=ode->next_spring;
  while (tmps!=&ode->next_spring) {
    tmps->rest_len=D3Dist(&tmps->end1->x,&tmps->end2->x);
    tmps=tmps->next;
  }
}

U0 BreakConnectors()
{
  MySpring *tmps=ode->next_spring,*tmps1;
  while (tmps!=&ode->next_spring) {
    tmps1=tmps->next;
    if (tmps->type==EMD_CONNECTOR &&
          Bt(kbd.down_bitmap,action_scan_codes[tmps->action_key-'0'])) {
      QueRem(tmps);
      Free(tmps);
    }
    tmps=tmps1;
  }
}

U0 Init()
{
  I64 i;
  task=Fs;
  for (i=0;i<=9;i++)
    action_scan_codes[i]=Char2ScanCode('0'+i);
  for (i=0;i<STARS_NUM;i++) {
    stars_x[i]=RandU32%8192-4096;
    stars_y[i]=RandU32%8192-4096;
  }
  next_action_key='1';
  zoom=1.0;
  ode=ODENew(0,1e-4,ODEF_HAS_MASSES);
  ode->derive=&MyDerivative;
  ode->acceleration_limit=5e3;
  ode->drag_v2=0.000002;
  ode->drag_v3=0.0000001;
  QueIns(ode,Fs->last_ode);
}

U0 CleanUp()
{
  if (ode) {
    QueRem(ode);
    QueDel(&ode->next_mass,TRUE);
    QueDel(&ode->next_spring,TRUE);
    ODEDel(ode);
    ode=NULL;
  }
}

U0 PlayShip()
{
  I64 arg1,arg2;
  F64 last_noise=0;
  Bool okay;
  ODEPause(ode,OFF);
  MenuPush(
        "File {"
        "  Abort(,CH_SHIFT_ESC);"
        "  Exit(,CH_ESC);"
        "}"
        "Edit {"
        "  EditShip(,CH_SPACE);"
        "}"
        "Play {"
        "  Center(,'c');"
        "  Damp(,'d');"
        "  Action0(,'0');"
        "  Action1(,'1');"
        "  Action2(,'2');"
        "  Action3(,'3');"
        "  Action4(,'4');"
        "  Action5(,'5');"
        "  Action6(,'6');"
        "  Action7(,'7');"
        "  Action8(,'8');"
        "  Action9(,'9');"
        "}"
        "View {"
        "  ZoomIn(,'z');"
        "  ZoomOut(,'Z');"
        "}"
        );
  DocClear;
  try {
    while (main_mode_bttn.state==MMD_PLAY) {
      BreakConnectors;
      switch (ScanMsg(&arg1,&arg2,1<<MSG_KEY_DOWN|1<<MSG_KEY_UP)) {
        case MSG_KEY_DOWN:
          switch (arg1) {
            case '0'...'9':
              if (tS>last_noise+0.25) {
                Noise(250,18,46);
                last_noise=tS;
              }
              break;
            case 'z':
              Spawn(&Zoom,2.0(I64));
              break;
            case 'Z':
              Spawn(&Zoom,0.5(I64));
              break;
            case 'c':
              CenterMasses;
              break;
            case 'd':
              ode->drag_v2=0.002;
              ode->drag_v3=0.0001;
              break;
            case CH_SPACE:
              if (++main_mode_bttn.state==MMD_MODES_NUM)
                main_mode_bttn.state=0;
              GetMsg(,,1<<MSG_KEY_UP);
              goto ps_done;
            case CH_SHIFT_ESC:
            case CH_ESC:
              throw;
          }
          break;
        case MSG_KEY_UP:
          switch (arg1) {
            case 'd':
              ode->drag_v2=0.000002;
              ode->drag_v3=0.0000001;
              break;
          }
          break;
      }
      Refresh;
    }
ps_done: //Don't goto out of try
    okay=TRUE;
  } catch {
    Fs->catch_except=TRUE;
    okay=FALSE;
  }
  MenuPop;
  if (!okay)
    throw;
}

