              edit_mode_bttn.state=EMD_MASS;
              break;
            case 'n':
              edit_mode_bttn.state=EMD_CONNECTOR;
              break;
            case 's':
              edit_mode_bttn.state=EMD_SPRING;
              break;
            case 't':
              edit_mode_bttn.state=EMD_THRUSTER;
              break;
            case 'z':
              Spawn(&Zoom,2.0(I64));
              break;
            case 'Z':
              Spawn(&Zoom,0.5(I64));
              break;
