              if (++main_mode_bttn.state==MMD_MODES_NUM)
                main_mode_bttn.state=0;
              GetMsg(,,1<<MSG_KEY_UP);
              goto es_done;
            case CH_SHIFT_ESC:
            case CH_ESC:
              throw;
          }
