U0 ExplosionDraw(CDC *dc,Explosion *tmpe,I64 y)
{
  I64 i,n1,n2,n3,n4,n5;
  F64 t=(tS-tmpe->t0)/(tmpe->tf-tmpe->t0);
  Seed(tmpe->num+1);

  switch (tmpe->type) {
    case ET_MAN:        n1=8;   n2=0;  n3=0;  n4=18;  n5=28;    break;
    case ET_TANK:       n1=64;  n2=14; n3=24; n4=60;  n5=90;    break;
    case ET_MISSILE:    n1=128; n2=30; n3=60; n4=100; n5=200;   break;
    case ET_BUILDING:   n1=128; n2=80; n3=80; n4=200; n5=300;   break;
  }
  for (i=0;i<n1;i++) {
    if (i&2)
      switch (tmpe->type) {
        case ET_MAN:
          if (i&1)
            dc->color=WHITE;
          else
            dc->color=LTGRAY;
          break;
        case ET_MISSILE:
          if (i&1) {
            if (i&4)
              dc->color=RED;
            else
              dc->color=DKGRAY;
          } else
            dc->color=YELLOW;
          break;
        case ET_TANK:
          if (i&1) {
            if (i&4)
              dc->color=RED;
            else
              dc->color=DKGRAY;
          } else
            dc->color=LTRED;
          break;
        case ET_BUILDING:
          if (i&1) {
            if (i&4)
              dc->color=BLACK;
            else
              dc->color=DKGRAY;
          } else
            dc->color=LTGRAY;
          break;
      }
    else if (i&1)
      dc->color=WHITE;
    else
      dc->color=LTGRAY;
    GrLine(dc,tmpe->x+n2*(Rand-.5),y+n3/2*Rand,
          tmpe->x+n4*t*(Rand-.5),y-n5/2*t*Rand);
  }
}

