  U8 *tmps,**_tmps;
  F64 tt,ts=tS;

  for (i=Gs->num;i<E_NUM;i+=mp_cnt) {
    tmpe=&e[i];
    yy=(tmpe->y-scroll_y)&(MAP_HEIGHT-1);
    if (-32<=yy<=task->pix_bottom+32 && !tmpe->dead) {
      ExplosionDraw(dc,tmpe,yy);
      if (tS>tmpe->tf)
        tmpe->dead=TRUE;
    }
  }
  for (i=lo;i<hi;i++) {
    tmpu=&u[i];
    yy=(tmpu->y-scroll_y)&(MAP_HEIGHT-1);
    if (-32<=yy<=task->pix_bottom+32) {
      if (!tmpu->dead) {
        Mat4x4IdentEqu(r);
        Mat4x4RotY(r,tmpu->é);
        Mat4x4RotX(r,ã/6);
        Mat4x4Scale(r,0.3);
        if (tmpu->tank)
          Sprite3Mat4x4B(dc,tmpu->x,yy,GR_Z_ALL,,r);
        else {
          if (tmpu->best_dd<(2*HACK_DIST)*(2*HACK_DIST)) {//It's neat so times 2
            if (tmpu->friendly)
              _tmps=friendly_hacking_imgs;
            else
              _tmps=enemy_hacking_imgs;
            tt=4*Wrap(tmpu->phase+20*ts,0)/(2*ã);
          } else {
            if (tmpu->friendly) {
              if (tmpu->CIA && Blink)
                _tmps=CIA_neeger_imgs;
              else
                _tmps=friendly_imgs;
            } else
              _tmps=enemy_imgs;
            tt=4*Wrap(tmpu->phase+5*ts,0)/(2*ã);
          }
          phase=tt; tt%=1.0;
          tmps=SpriteInterpolate(tt,_tmps[phase&3],_tmps[(phase+1)&3]);
          Sprite3Mat4x4B(dc,tmpu->x,yy,GR_Z_ALL,tmps,r);
          Free(tmps);
        }
      }
    }
  }

  dc->depth_buf=NULL;
  DCDel(dc);
  LBtr(&mp_not_done_flags,Gs->num);
  Seed; //Return Seth task to timer-based.
}

U0 MissilePos(I64 m,F64 é,I64 *_x,I64 *_y)
{
  I64 n;
  if (m<2)
    n=-1;
