  GrPrint(dc,0,8,"Total Score:%,d High Score:%,d",
        total_score,best_score);
}

Explosion *ExplosionNew(I64 x,I64 y)
{
  I64 i;
  for (i=0;i<E_NUM;i++)
    if (e[i].dead) {
