  F64 a;
  Bullet *tmpb;
  for (i=0;i<B_NUM-1;i++)
    if (b[i].dead)
      break;
  tmpb=&b[i];

  j=x+28.0*Cos(é);
  tmpb->x=j<<32;
  j=y+28.0*Sin(é);
  tmpb->y=j<<32;

  tmpb->dx2=(B_SPEED*Cos(é)+dx)*0x100000000;
  tmpb->dy2= B_SPEED*Sin(é)*0x100000000;
  a=Arg(tmpb->dx2,tmpb->dy2);
  tmpb->dx=Sin(a)*0x100000000;
  tmpb->dy=Cos(a)*0x100000000;
  bullets_fired++;
  tmpb->dead=FALSE;
  tmpb->missile=FALSE;
  if (!snd_timeout) {
    snd_timeout=tS+0.0005;
    Snd(74);
  }
}

Bool FireMissile(I64 n)
{
  I64 i,m;
  F64 a;
  Bullet *tmpb;
  Bool res=FALSE;

  m=n;
  if (Btr(&missile_bmp,++m) || Btr(&missile_bmp,++m))
    res=TRUE;

  if (res) {
    for (i=0;i<B_NUM-1;i++)
      if (b[i].dead)
        break;
    tmpb=&b[i];

    MissilePos(m,é,&tmpb->x,&tmpb->y);
    tmpb->x<<=32;
    tmpb->y<<=32;

    tmpb->dx2=(B_SPEED*Cos(é)+dx)*0x100000000;
    tmpb->dy2= B_SPEED*Sin(é)*0x100000000;
    a=Arg(tmpb->dx2,tmpb->dy2);
    tmpb->dx=Sin(a)*0x100000000;
    tmpb->dy=Cos(a)*0x100000000;
    tmpb->dead=FALSE;
    tmpb->missile=TRUE;
    if (!snd_timeout) {
      snd_timeout=tS+0.0005;
      Snd(74);
    }
  }
}

U0 MenMove(I64 phase_group)
{
  I64 i,j,dd,best,best_dd;
  for (i=phase_group;i<U_FRIENDLY_NUM;i+=PHASES_GROUPS) {
    if (!u[i].dead) {
      best=U_FRIENDLY_NUM;
      best_dd=I64_MAX;
      for (j=U_FRIENDLY_NUM;j<U_NUM;j++) {
        if (!u[j].dead) {
          dd=SqrI64(u[i].x-u[j].x)+SqrI64(u[i].y-u[j].y);
          if (dd<best_dd) {
            best_dd=dd;
            best=j;
          }
        }
      }
      u[i].best_dd=best_dd;
      if (best_dd!=I64_MAX) {
        u[i].x+=4*SignI64(u[best].x-u[i].x);
        u[i].y+=4*SignI64(u[best].y-u[i].y);
        u[i].é=Arg(u[best].x-u[i].x,u[best].y-u[i].y);
      }
    }
  }
  for (i=U_FRIENDLY_NUM+phase_group;i<U_NUM;i+=PHASES_GROUPS) {
    if (!u[i].dead) {
      best=0;
      best_dd=I64_MAX;
      for (j=0;j<U_FRIENDLY_NUM;j++) {
        if (!u[j].dead) {
          dd=SqrI64(u[i].x-u[j].x)+SqrI64(u[i].y-u[j].y);
          if (dd<best_dd) {
            best_dd=dd;
            best=j;
          }
        }
      }
      u[i].best_dd=best_dd;
      if (best_dd!=I64_MAX) {
        u[i].x+=4*SignI64(u[best].x-u[i].x);
        u[i].y+=4*SignI64(u[best].y-u[i].y);
        u[i].é=Arg(u[best].x-u[i].x,u[best].y-u[i].y);
      }
    }
  }
}

