U0 MissileDel(Missile *tmpmi)
{
  I64 i;
  if (tmpmi->active) {
    QueRem(tmpmi);
    for(i=0;i<5;i++)
      QueRem(&tmpmi->s[i]);
    QueRem(&tmpmi->p_front);
    QueRem(&tmpmi->p_back);
    tmpmi->active=FALSE;
  }
}

U0 ShipDel(Ship *tmpsp)
{
  I64 i;
  if (!tmpsp) return;
  for (i=0;i<tmpsp->masses;i++)
    QueRem(&tmpsp->p[i]);
  for (i=0;i<tmpsp->springs;i++)
    QueRem(&tmpsp->s[i]);
  for (i=0;i<2;i++)
    MissileDel(&tmpsp->missiles[i]);
  QueRem(tmpsp);
  Free(tmpsp);
  remaining--;
}

U0 PlaceShip(I64 type)
{
  Ship *tmpsp;
  if (CheckOverlap)
    return;
  while (TRUE) {
    tmpsp=ShipNew(RandU16%(Fs->pix_width-20)+10,
          RandU16%(Fs->pix_height-20)+10,type);
    if (CheckOverlap)
      ShipDel(tmpsp);
    else
      break;
  }
}

