              tmpi->ic_code=IC_IMM_I64;
            } else {
              tmpi->ic_data(F64)=-tmpi1->ic_data(F64);
              tmpi->ic_code=IC_IMM_F64;
            }
          }
          if (tmpc1->type&HTT_INTERNAL_TYPE && tmpc1->raw_type&RTF_UNSIGNED)
            tmpi->ic_class=cmp.internal_types[tmpc1->raw_type-1];
