                tmpi->ic_data=tmpi1->ic_data(U64)>>tmpi2->ic_data(U64);
              else
                tmpi->ic_data=tmpi1->ic_data(I64)>>tmpi2->ic_data(I64);
              tmpi->ic_code=IC_IMM_I64;
            } else {
              tmpi->ic_data(F64)=tmpi1->ic_data(F64) >> tmpi2->ic_data(F64);
              tmpi->ic_code=IC_IMM_F64;
            }
