                    tmpi2->ic_data(F64);
              tmpi->ic_code=IC_IMM_F64;
            }
          } else {
            if (tmpi1->ic_code==IC_ABS_ADDR&&tmpi2->ic_code==IC_IMM_I64) {
              tmpi->ic_flags|=tmpi1->ic_flags|tmpi2->ic_flags;
              tmpi->ic_data=tmpi1->ic_data+tmpi2->ic_data;
