                } else
                  if (tmpi1->ic_code==IC_ADD ||
                        tmpi1->ic_code==IC_SUB) {
                    if (tmpi1->t.arg1_tree->ic_code==IC_IMM_I64) {
                      tmpi1->ic_flags|=tmpi->ic_flags;
                      tmpi1->t.arg1_tree->ic_data-=tmpi2->ic_data;
                      tmpi1->ic_class2=tmpi->ic_class2;
