U0 DumpStruct(U8 *_d,U8 *class_name=lastclass)
{//lastclass is keyword.  See ::/Demo/LastClass.TC.
  CHashClass *tmpc=HashFind(class_name,Fs->hash_table,HTT_CLASS);
  U8 *print_str;
  I64 *q,dft_val;
  U0 (* fp_output_fun)(I64 i);
  F64 percentile;
  if (!tmpc) return;
  CMemberLst *ml;
