U8 *SuggestMatchForm(U8 *src)
{
  I64 ch,ch1=0;
  U8 *res=MStrUtil(src,SUF_TO_UPPER),*dst;
  dst=src=res;
  while (ch=*src++)  {
    if (!StrOcc("AEIOU",ch)) {
      if (ch=='C') ch='K';
      if (ch=='Z') ch='S';
      if (ch!=ch1) //double chars to single
        *dst++=ch;
    }
    ch1=ch;
  }
  *dst=0;
  return res;
}

