class Trooper
{
  I64 x,y,dx,dy,att,def,rng,player;
  F64 animate_time_base,fire_end_time;
  Trooper *target;
};

#define TROOPERS_NUM 100
Trooper tr[2][TROOPERS_NUM];

Bool time_lapse=FALSE;

#define TAP_MODE_RADIUS 50
