U0 DoAiTarget()
{
  I64 i,j;
  Trooper *tmpt1,*tmpt0;
  for (i=0;i<10;i++) {
    tmpt0=&tr[0][ai_targets[i]];
    for (j=0;j<10;j++) {
      tmpt1=&tr[1][i*10+j];
      tmpt1->dx=(tmpt0->x-tmpt1->x)>>11;
      tmpt1->dy=(tmpt0->y-tmpt1->y)>>11;
