U0 BlackDiamond()
{
  I64 ch,sc;

  MenuPush(
        "File {"
        "  New(,'\n');"
        "  Restart(,CH_SPACE);"
        "  Abort(,CH_SHIFT_ESC);"
        "  Exit(,CH_ESC);"
        "}"
        "Play {"
        "  Up(,,SC_CURSOR_UP);"
        "  Down(,,SC_CURSOR_DOWN);"
        "  Left(,,SC_CURSOR_LEFT);"
        "  Right(,,SC_CURSOR_RIGHT);"
        "}"
        );
  SettingsPush; //See SettingsPush
  AutoComplete;
  WinBorder;
  WinMax;
  DocCursor;
  DocClear;
  Fs->draw_it=&DrawIt;

  Init;
  try {
    while (TRUE) {
bd_restart:
      MemCpy(obj_x,obj_saved_x,sizeof(obj_x)); //Wolves move. We must reset the
      MemCpy(obj_y,obj_saved_y,sizeof(obj_y)); //wolves if running same game.

      game_over=FALSE;
      scrn_top_y=0;
      x=Fs->pix_width>>1; y=0;
      penalty=0;
      while (TRUE) {
        if (ScanKey(&ch,&sc)) {
          switch (ch) {
            case 0:
              if (!game_over)
                switch (sc.u8[0]) {
                  case SC_CURSOR_RIGHT:
                    x+=10;
                    if (x>=Fs->pix_width) x-=Fs->pix_width;
                    break;
                  case SC_CURSOR_LEFT:
                    x-=10;
                    if (x<0) x+=Fs->pix_width;
                    break;
                  case SC_CURSOR_UP:
                    y-=10;
                    break;
                  case SC_CURSOR_DOWN:
                    y+=10;
                    break;
                }
              break;

            case CH_ESC:
            case CH_SHIFT_ESC:
              goto bd_done;

            case '\n':
              Init;
              goto bd_restart;

            case CH_SPACE:
              game_over=TRUE;
              while (scrn_top_y>0||y>0) {//Animate going back to top.
                scrn_top_y=MaxI64(0,scrn_top_y-4);
                y=MaxI64(0,y-4);
                x+=SignI64(Fs->pix_width>>1-x);
                Sleep(1);
              }
              Snd;
              goto bd_restart;
          }
//Don't want keystrokes building-up in the buf.
          FlushMsgs;
        }
        if (!game_over) {
          y+=2;
          scrn_top_y++;
          if (y-scrn_top_y>Fs->pix_height) {//Animate scrolling scrn.
            while (y-scrn_top_y>Fs->pix_height>>1) {
              scrn_top_y+=2;
              Sleep(1);
            }
          }
          if (y>=MAP_HEIGHT) {
            game_over=TRUE;
            Beep;
            if (penalty<=best_score) {
              best_score=penalty;
              Beep;
            }
          }
        }
        Sleep(10);
      }
    }
bd_done:
  } catch
    PutExcept;
  SettingsPop;
  MenuPop;
  RegWrite("TempleOS/BlackDiamond","I64 best_score=%d;\n",best_score);
}

