*/

#define MAP_WIDTH       (TEXT_COLS*2)
#define MAP_HEIGHT      (TEXT_ROWS*2)

#define CH_WATER        '^'
#define CH_LAND         CH_SPACE
#define CH_TREE         '*'

U16 map[MAP_HEIGHT][MAP_WIDTH];

