  try {
    while (TRUE) {
      switch (GetMsg(&ch,&sc,1<<MSG_KEY_DOWN|1<<MSG_KEY_UP)) {
        case MSG_KEY_DOWN:
          switch (ch) {
            case '\n':
              Init;
              break;
            case CH_SPACE:
              man_attack=TRUE;
              break;
            case CH_ESC:
            case CH_SHIFT_ESC:
              goto dg_done;
            case 0:
              switch (sc.u8[0]) {
                case SC_CURSOR_RIGHT:
                  if (man_attack) {
                    man_dx=1;
                    man_dy=0;
                    Attack;
                  } else
                    if (man_x+1<map_width &&
                          map[man_y*map_width+(man_x+1)]==DKGRAY) {
                      man_x++;
                      if (man_x-scrn_x>SCRN_WIDTH/2-3) {
                        scrn_x+=SCRN_WIDTH/2;
                        if (scrn_x+SCRN_WIDTH/2>map_width)
                          scrn_x=map_width-SCRN_WIDTH/2;
                      }
                    }
                  break;
                case SC_CURSOR_LEFT:
                  if (man_attack) {
                    man_dx=-1;
                    man_dy=0;
                    Attack;
                  } else
                    if (man_x-1>=0 &&
                          map[man_y*map_width+(man_x-1)]==DKGRAY) {
                      man_x--;
                      if (man_x-scrn_x<-SCRN_WIDTH/2+3) {
                        scrn_x-=SCRN_WIDTH/2;
                        if (scrn_x-SCRN_WIDTH/2<0)
                          scrn_x=SCRN_WIDTH/2;
                      }
                    }
                  break;
                case SC_CURSOR_UP:
                  if (man_attack) {
                    man_dx=0;
                    man_dy=-1;
                    Attack;
                  } else
                    if (man_y-1>=0 &&
                          map[(man_y-1)*map_width+man_x]==DKGRAY) {
                      man_y--;
                      if (man_y-scrn_y<-SCRN_HEIGHT/2+3) {
                        scrn_y-=SCRN_HEIGHT/2;
                        if (scrn_y-SCRN_HEIGHT/2<0)
                          scrn_y=SCRN_HEIGHT/2;
                      }
                    }
                  break;
                case SC_CURSOR_DOWN:
                  if (man_attack) {
                    man_dx=0;
                    man_dy=1;
                    Attack;
                  } else
                    if (man_y+1<map_height &&
                          map[(man_y+1)*map_width+man_x]==DKGRAY) {
                      man_y++;
                      if (man_y-scrn_y>SCRN_HEIGHT/2-3) {
                        scrn_y+=SCRN_HEIGHT/2;
                        if (scrn_y+SCRN_HEIGHT/2>map_height)
                          scrn_y=map_height-SCRN_HEIGHT/2;
                      }
                    }
                  break;
              }
          }
          break;
        case MSG_KEY_UP:
          if (ch==CH_SPACE)
            man_attack=FALSE;
          break;
      }
    }
dg_done:
    GetMsg(,,1<<MSG_KEY_UP);
  } catch
    PutExcept;
  SettingsPop;
  CleanUp;
  MenuPop;
  RegWrite("TempleOS/DunGen","F64 best_score=%5.4f;\n",best_score);
}

