  for (i=0;i<BUGS_NUM;i++) {
    bugs_dead[i]=FALSE;
    bugs_x[i]=RandU16;
    bugs_y[i]=RandU16;
    bugs_glow_phase[i]=GLOW_PERIOD*Rand;
  }
  Suspend(Fs->song_task,FALSE);
  flap_time=eat_timeout=0;
  delta_phase=game_tf=0;
  game_t0=tS;
}

