        SquadronRem(tmpo);
      QueRem(tmpo);
      if (tmpo->squadron>=0)
        LBts(&squadrons[tmpo->squadron].dead_mask,tmpo->member_num);
      num_alive[tmpo->player]--;
      Free(tmpo);
    }
  }
}

























