U0 UpdateRoad()
{
  F64 t0=tS;
  distance+=speed*(t0-t_last);
  t_last=t0;
  while (distance>1.0) {
    road_trend=ClampI64(road_trend+SignI64(RandU16%3-1),-5,5);
    road_x[road_ptr&(ROAD_NUM-1)]=
          road_x[(road_ptr-1)&(ROAD_NUM-1)]+=road_trend/3;
    road_ptr++;
    distance-=1.0;
  }
}

