#define STK_SIZE 2048
//We would put these as local vars
//in SolveMaze() but the system stk size
//is limited, so it's a bad habit.The heap
//is the normal TempleOS technique, but
//it's a pain in this case.
I64     stk_ptr,
        stk_x  [STK_SIZE],
        stk_y  [STK_SIZE],
        stk_dir[STK_SIZE];

//Four directions:
//  0=Up,1=right,2=down,3=left
I64     dir_x[4]={ 0,+1, 0,-1},  // Could use gr_x_offsets2,gr_y_offsets2
        dir_y[4]={+1, 0,-1, 0};

U0 SolveMaze(I64 x,I64 y)
{
  I64 dir=0;
  stk_ptr=0;
  stk_x[stk_ptr]=x;
  stk_y[stk_ptr]=y;
  stk_dir[stk_ptr++]=dir;
  while (TRUE) {
    if (!(0<=x<MinI64(Fs->win_width,TEXT_COLS)) ||
          !(0<=y<MinI64(Fs->win_height,TEXT_ROWS)) ) {
      Beep;Beep;
      break;
    }
    if (!text[y][x].u8[0])
      text[y][x]='.'+ATTR;
    x+=dir_x[dir];
    y+=dir_y[dir];
//u8.[0] is the ASCII
    if (text[y][x].u8[0]) {
      x-=dir_x[dir];
      y-=dir_y[dir];
      if (++dir==4) {
        if (--stk_ptr<0) return;
        x=stk_x[stk_ptr];
        y=stk_y[stk_ptr];
        dir=stk_dir[stk_ptr];
      }
    } else {
      dir=0;
      stk_x[stk_ptr]=x;
      stk_y[stk_ptr]=y;
      stk_dir[stk_ptr++]=dir;
      if (stk_ptr==STK_SIZE) return;
      Sleep(100);
      if (ScanChar)
        throw;
    }
  }
}

