U0 TheDead()
{
  I64 i,j,i1,j1,k=0,sc=0,ch=0,msg_code,arg1,arg2;
  Bool gun_on=FALSE;

  MenuPush(
        "File {"
        "  Abort(,CH_SHIFT_ESC);"
        "  Exit(,CH_ESC);"
        "}"
        "Play {"
        "  Fire(,CH_SPACE);"
        "  Up(,,SC_CURSOR_UP);"
        "  Down(,,SC_CURSOR_DOWN);"
        "}"
        );
  SettingsPush; //See SettingsPush
  AutoComplete;
  WinBorder;
  WinMax;
  DocCursor;
  DocClear;
  Fs->song_task=Spawn(&SongTask,NULL,"Song",,Fs);
  Fs->draw_it=&DrawIt;

  try {
    do {
      if (msg_code=ScanMsg(&arg1,&arg2,1<<MSG_KEY_DOWN | 1<<MSG_KEY_UP)) {
//With keyboard msgs, the two msg args
        //are the scan code and ascii val for the key.
        sc=arg2; ch=arg1;

        if (msg_code==MSG_KEY_DOWN) {
//The low byte of the scan code identifies the key.
          if (sc.u8[0]==SC_CURSOR_DOWN) {
            y+=10;
            if (y>GR_HEIGHT-30)
              y=GR_HEIGHT-30;
          } else if (sc.u8[0]==SC_CURSOR_UP) {
            y-=10;
            if (y<0)
              y=0;
          } else if (sc.u8[0]==SC_CURSOR_RIGHT ||
                ch==CH_SPACE)
            gun_on=TRUE;
        } else if (msg_code==MSG_KEY_UP) {
          if (sc.u8[0]==SC_CURSOR_RIGHT ||
                ch==CH_SPACE)
            gun_on=FALSE;
        }
      }

      i=bullets_out;
      while (i!=bullets_in) {
        j=i++ &(BULLETS_NUM-1);
        bx[j]+=5;
        if (bx[j]>GR_WIDTH)
          bullets_out++;
        else {
          i1=dead_out;
          while (i1!=dead_in) {
            j1=i1++ &(DEAD_NUM-1);
            if (gy[j1]<=by[j]<=gy[j1]+38 &&
                  gx[j1]<=bx[j]<=gx[j1]+40)
              g_dead[j1]=TRUE;
          }
        }
      }

      if (gun_on) {
        j=bullets_in&(BULLETS_NUM-1);
        bx[j]=x+32;
        by[j]=y+14;
        bullets_in++;
      }

      //Runs one out of four passes through this loop.
      if (!(k % 4)) {
        i=dead_out;
        while (i!=dead_in) {
          j=i++ &(DEAD_NUM-1);
          gx[j]-=1;
          if (gx[j]<25)
            dead_out++;
        }
      }

      //Runs one out of 150 passes through this loop.
      if (!(k%150)) {
        j=dead_in&(DEAD_NUM-1);
        gx[j]=GR_WIDTH-30;
        gy[j]=RandU32%(GR_HEIGHT-50)+25;
        g_dead[j]=FALSE;
        dead_in++;
      }
      k++;

      Sleep(10); //Swap this task out for 10 miliseconds.
    } while (ch!=CH_ESC && ch!=CH_SHIFT_ESC);
  } catch
    PutExcept;
  SettingsPop;
  MenuPop;
}

