U0 TreeCheckers()
{
  I64 msg_code,arg1,arg2,ch,sc;
  Unit *tmpu;

  SettingsPush; //See SettingsPush
  MenuPush(
        "File {"
        "  Abort(,CH_SHIFT_ESC);"
        "  Exit(,CH_ESC);"
        "}"
        "Play {"
        "  Restart(,'\n');"
        "}"
        );
  AutoComplete;
  WinBorder;
  WinMax;
  DocCursor;
  DocClear;
  PopUpOk("Step on the link mid points.\n");
  Fs->win_inhibit=WIG_TASK_DFT-WIF_SELF_FOCUS
        -WIF_SELF_BORDER-WIF_FOCUS_TASK_MENU;
  try {
cn_start:
    Init;
    tmpu=NULL;
    show_start=FALSE;
    Fs->draw_it=&DrawIt;
    while (TRUE) {
      msg_code=GetMsg(&arg1,&arg2,
            1<<MSG_KEY_DOWN+1<<MSG_MS_L_DOWN+1<<MSG_MS_L_UP+1<<MSG_MS_MOVE);
      switch (msg_code) {
        case MSG_KEY_DOWN:
          switch (arg1) {
            case '\n':
              CleanUp;
              goto cn_start;
            case CH_ESC:
            case CH_SHIFT_ESC:
              goto cn_done;
          }
          break;
        case MSG_MS_L_DOWN:
          if (num_alive[0]>1 && num_alive[1]>1) {
            tmpu=UnitFind(arg1,arg2,cur_player);
            end_x=start_x=tmpu->x;
            end_y=start_y=tmpu->y;
            show_start=TRUE;
          }
          break;
        case MSG_MS_MOVE:
          if (tmpu)
            UnitMove(tmpu,arg1,arg2);
          break;
        case MSG_MS_L_UP:
          UnitMove(tmpu,arg1,arg2);
          KillsChk(tmpu->x,tmpu->y,cur_player);
          show_start=FALSE;
          tmpu=NULL;
          cur_player=1-cur_player;
          break;
      }
    }
cn_done:
    GetMsg(,,1<<MSG_KEY_UP);
  } catch
    PutExcept;
  SettingsPop;
  CleanUp;
  MenuPop;
}

TreeCheckers;

























































































