          Init;
          break;
        case CH_ESC:
        case CH_SHIFT_ESC:
          goto ws_done;
        case CH_SPACE:
          BurnTrees;
          break;
        case 0:
          switch (sc.u8[0]) {
            start:
              case SC_CURSOR_RIGHT:
                if (king_x+KING_STEP<Fs->pix_width-BORDER)
                  king_x+=KING_STEP;
                king_é=0;
                break;
              case SC_CURSOR_LEFT:
                if (king_x-KING_STEP>=BORDER)
                  king_x-=KING_STEP;
                king_é=ã;
                break;
              case SC_CURSOR_DOWN:
                if (king_y+KING_STEP<Fs->pix_height-BORDER)
                  king_y+=KING_STEP;
                king_é=-ã/2;
                break;
              case SC_CURSOR_UP:
                if (king_y-KING_STEP>=BORDER)
                  king_y-=KING_STEP;
                king_é=ã/2;
                break;
            end:
              king_mS=0;
              king_phase=(king_phase+2)&2;
              StepNew(Fs,king_x,king_y,king_é,king_phase&2,TRUE);
              king_timeout=tS+0.5;
              break;
          }
      }
    }
ws_done:
  } catch
    PutExcept;
  SettingsPop;
  CleanUp;
  MenuPop;
  RegWrite("TempleOS/Wenceslas","F64 best_score=%5.4f;\n",best_score);
}

