  GrLine(dc,x+str_h/2*Cos(bow_é+ã/2)+str_w*Cos(bow_é),
        y+str_h/2*Sin(bow_é+ã/2)+str_w*Sin(bow_é),
        x,y);

  MemSet(ctrl,0,sizeof(ctrl));
  ctrl[0].x=x-str_h/2*Cos(bow_é+ã/2)+str_w*Cos(bow_é);
  ctrl[0].y=y-str_h/2*Sin(bow_é+ã/2)+str_w*Sin(bow_é);
  ctrl[1].x=x-0.75*str_h/2*Cos(bow_é+ã/2)+draw_len/2*Cos(bow_é)+
        str_w*Cos(bow_é);
  ctrl[1].y=y-0.75*str_h/2*Sin(bow_é+ã/2)+draw_len/2*Sin(bow_é)+
        str_w*Sin(bow_é);
  ctrl[2].x=x+draw_len/2*Cos(bow_é)+str_w*Cos(bow_é);
