  ctrl[3].y=y+0.75*str_h/2*Sin(bow_é+ã/2)+draw_len/2*Sin(bow_é)+
        str_w*Sin(bow_é);
  ctrl[4].x=x+str_h/2*Cos(bow_é+ã/2)+str_w*Cos(bow_é);
  ctrl[4].y=y+str_h/2*Sin(bow_é+ã/2)+str_w*Sin(bow_é);

