  if (bow_drawn)
    Sprite3ZB(dc,x,y,0,,bow_é);

  tmpa=head.next;
  while (tmpa!=&head) {
    é=Arg(tmpa->dx,tmpa->dy);
    Sprite3ZB(dc,tmpa->x,tmpa->y,0,,é);
    tmpa=tmpa->next;
  }
