U0 ZOTransform(CDC *dc,I64 *x,I64 *y,I64 *z)
{
  I64 zz;
  Mat4x4MulXYZ(dc->r,x,y,z);
  zz=*z;
  if (zz<1) zz=1;
  *x=SCRN_SCALE/2* *x/zz;
  *y=SCRN_SCALE/2* (*y+TANK_HEIGHT)/zz;
  *x+=dc->x;
  *y+=dc->y;
  *z+=dc->z;
}

U0 DrawIt(CTask *task,CDC *dc)
{
  Obj *tmpo;
  I64 i,dd,y,w=task->pix_width,h=task->pix_height,cx=w>>1,cy=h>>1;
  U8 *img;
  F64 tt,é;

  é=640*Wrap(2*us.é)/ã;
  Sprite3(dc,é-1280,90,0,);
  Sprite3(dc,é     ,90,0,);
  Sprite3(dc,é+1280,90,0,);

  DCDepthBufAlloc(dc);
  dc->transform=&ZOTransform;
  dc->x=cx;
  dc->y=cy;
  Mat4x4TranslationEqu(dc->r,-us.x,-us.y,-us.z);
  Mat4x4RotY(dc->r,us.é-ã/2);
  Mat4x4RotX(dc->r,ã/16);

  dc->flags|=DCF_TRANSFORMATION;
  for (i=0;i<THEM_NUM;i++) {
    y=them[i].y;
    tmpo=shots.next;
    while (tmpo!=&shots) {
      dd=SqrI64(them[i].x-tmpo->x)+SqrI64(them[i].z-tmpo->z);
      if (dd<SCRN_SCALE/2*SCRN_SCALE/2) {
        y-=Sqrt(dd);
        if (!them[i].hit) {
          them[i].hit=TRUE;
          if (!--num_them) {
            tf=tS;
            if (tf-t0<best_score)
              best_score=tf-t0;
          }
        }
      }
      tmpo=tmpo->next;
    }
    if (them[i].hit)
      img=;
    else
      img=;
    Sprite3YB(dc,them[i].x,y,them[i].z,img,-them[i].é);
  }
  tmpo=shots.next;
  while (tmpo!=&shots) {
    Sprite3YB(dc,tmpo->x,tmpo->y,tmpo->z,,-tmpo->é);
    tmpo=tmpo->next;
  }
  dc->flags&=~DCF_TRANSFORMATION;
  dc->color=LTGREEN;
