  AutoComplete;
  WinBorder;
  WinMax;
  DocCursor;
  DocClear;
  TurtleInit(&tt);
  SetMenu;
  Fs->win_inhibit=WIG_TASK_DFT-WIF_FOCUS_TASK_MENU
        -WIF_SELF_FOCUS-WIF_SELF_GRAB_SCROLL;
  Fs->draw_it=&DrawIt;
  try {
    while (TRUE) {
      switch (GetMsg(&arg1,&arg2,1<<MSG_KEY_DOWN|1<<MSG_MS_L_DOWN|
            1<<MSG_MS_R_DOWN|1<<MSG_MS_R_UP|1<<MSG_MS_MOVE)) {
        case MSG_MS_L_DOWN:
          tt.first=TRUE;
          tt.x=arg1;
          tt.y=arg2;
          break;
        case MSG_MS_R_DOWN:
          aim=TRUE;
          tt.é=Arg(arg1-tt.x,arg2-tt.y);
          break;
        case MSG_MS_MOVE:
          if (aim)
            tt.é=Arg(arg1-tt.x,arg2-tt.y);
          break;
        case MSG_MS_R_UP:
          tt.é=Arg(arg1-tt.x,arg2-tt.y);
          aim=FALSE;
          break;
        case MSG_KEY_DOWN:
          switch (arg1) {
            case 0:
              switch (arg2.u8[0]) {
                case SC_CURSOR_LEFT:
                  if (tt.dé_idx)
                    tt.dé_idx--;
                  break;
                case SC_CURSOR_RIGHT:
                  if (tt.dé_idx<ANGLES-1)
                    tt.dé_idx++;
                  break;
                case SC_CURSOR_UP:
                  tt.speed+=TURTLE_SPEED_STEP;
                  break;
                case SC_CURSOR_DOWN:
                  if (tt.speed>=TURTLE_SPEED_STEP)
                    tt.speed-=TURTLE_SPEED_STEP;
                  break;
              }
              break;
            case '0'...'9':
              tt.z=arg1-'0';
              SetMenu;
              break;
            case 'c':
              tt.middle=PopUpColor("Mid Color\n\n");
              tt.edge  =PopUpColor("Edge Color\n\n");
              break;
            case 'e':
              tt.ends=!tt.ends;
              break;
            case '+':
              tt.w++;
              break;
            case '-':
              if (tt.w)
                tt.w--;
              break;
            case '\n':
              DCFill(dc);
              TurtleInit(&tt);
              SetMenu;
              break;
            case CH_ESC:
            case CH_SHIFT_ESC:
              goto lt_done;
            case CH_SPACE:
              TurtleMove(dc,&tt,tt.edge,tt.middle);
              break;
          }
      }
    }
lt_done:
    GetMsg(,,1<<MSG_KEY_UP);
  } catch
    PutExcept;
  SettingsPop;
  DCFill(dc);
  DCDel(dc);
  MenuPop;
}

