U0 LightTable()
{
  I64 msg_code,mode=LTM_REFLECT_LINE,i,cnt,arg1,arg2,x1,y1,x2,y2;
  CD3I32 *c=MAlloc(PTS_NUM*sizeof(CD3I32));

  p_root_locks=0;
  MenuPush(
        "File {"
        "  Restart(,'\n');"
        "  Abort(,CH_SHIFT_ESC);"
        "  Exit(,CH_ESC);"
        "}"
        "Mode {"
        "  ReflectLine(,'0');"
        "  ReflectSpline(,'1');"
        "  RefractLine(,'2');"
        "  RefractSpline(,'3');"
        "  RefractFloodFill(,'4');"
        "  TestRay(,'5');"
        "}"
