        MOV     U64 CArcCtrl.next_entry[RSI],RAX
        INC     RDX
        CMP     U64 CArcCtrl.free_limit[RSI],RDX
        JNE     @@25
        INC     RCX
        MOV     U64 CArcCtrl.next_bits_in_use[RSI],RCX
        MOV     RAX,1
