#define CFG_HOME_DIR            4
#define CFG_NO_MP               5
#define CFG_TEXT_MODE           6
#define CFG_DONT_PROBE          7
#define CFG_MOUNT_IDE_AUTO      8
#define CFG_DBG_DISTRO  9
#define CFG_OPTIONS_NUM         10

#define CFG_HELP                10

class CKCfg
{
  U8 *dsk_cache_size_exp;
