        TEST    RSI,RSI
        JZ      RESTORE_SETH_TASK_IF_READY
        BT      U64 CTask.win_inhibit[RSI],WIf_SELF_FOCUS
        JC      I32 RESTORE_RSI_TASK
        LOCK
        BTR     U64 CTask.task_flags[RSI],TASKf_BREAK_LOCKED
        JNC     @@10
        LOCK
