U0 ScanFlags(U8 *_dst_flags,U8 *lst,U8 *src)
{/*More than 64 flags. Flags passed by ref.

Examples:
ScanFlags(&fuf_flags,Define("ST_FILE_UTIL_FLAGS"),fu_flags);

I64 flags=0;
ScanFlags(&flags,"R\0L\0Dump\0Scan\0","+Dump-R"); //Sets Bit#2, Clears Bit#0.
*/
  I64 i;
  U8 *buf,*ptr;
  if (src) {
    buf=MAlloc(StrLen(src)+1);
    while (*src) {
      while (*src && *src!='+' && *src!='-')
        src++;
      if (*src=='+') {
        src++;
        if (*src) {
          ptr=buf;
          while (*src && *src!='+' && *src!='-' &&
                *src!=CH_SPACE && *src!=CH_SHIFT_SPACE)
            *ptr++=*src++;
          *ptr=0;
          i=LstMatch(buf,lst);
          if (i>=0)
            LBts(_dst_flags,i);
          else {
            Free(buf);
            throw('ScanFlag');
          }
        }
      } else if (*src=='-') {
        src++;
        if (*src) {
          ptr=buf;
          while (*src && *src!='+' && *src!='-' &&
                *src!=CH_SPACE && *src!=CH_SHIFT_SPACE)
            *ptr++=*src++;
          *ptr=0;
          i=LstMatch(buf,lst);
          if (i>=0)
            LBtr(_dst_flags,i);
          else {
            Free(buf);
            throw('ScanFlag');
          }
        }
      }
    }
    Free(buf);
  }
}

