            }
            if (i<0)
              tmp_buf[k++]=sys_neg_pows_lets[-i];
            else if (i>0)
              tmp_buf[k++]=sys_pos_pows_lets[i];
            else if (len!=0)
              tmp_buf[k++]=CH_SPACE;
            if (!(flags&PRTF_DECIMAL)) {
              dec_len=len-k-2;
              if (flags&PRTF_NEG)
                dec_len--;
              if (j>0) {
