              if (d1>=10) {
                dec_len--;
                if (d1>=100)
                  dec_len--;
              }
            }
          } else {
            i=3;
            do tmp_buf[k++]=ModU64(&n,10)+'0';
            while (n && i--);
            if (flags&PRTF_NEG_E)
              tmp_buf[k++]='-';
            tmp_buf[k++]='e';
            if (!dec_len) {
              dec_len=len-k-2;
              if (flags&PRTF_NEG)
                dec_len--;
              d1=d+Pow10I64(-dec_len+1)/2;
              if (d1>=10) {
                dec_len--;
                if (d1>=100)
                  dec_len--;
              }
            }
          }
          if (flags&PRTF_COMMA) {
            if (len && dec_len>0 && !(dec_len&3))
              tmp_buf[k++]=',';
            dec_len-=dec_len/4;
          }
          goto sp_out_f;
        case 'X':
          if (cur_arg>=argc)
            throw('StrPrint');
          m=argv[cur_arg++];
          if (flags&PRTF_COMMA) {
            comma_fmt_cnt=comma_cnt=4;
            do {
              tmp_buf[k]= m&15 +'0';
              if (tmp_buf[k]>'9') tmp_buf[k]+='A'-0x3A;
              k++;
              m>>=4;
              if (!m) break;
              if (!--comma_cnt) {
                tmp_buf[k++]=',';
                comma_cnt=4;
              }
            } while (k<TMP_BUF_LEN-SLOP);
            goto sp_out_comma_num;
          } else {
            do {
              tmp_buf[k]= m&15 +'0';
              if (tmp_buf[k]>'9') tmp_buf[k]+='A'-0x3A;
              k++;
              m>>=4;
            } while (m && k<TMP_BUF_LEN-SLOP);
            goto sp_out_num;
          }
        case 'x':
          if (cur_arg>=argc)
            throw('StrPrint');
          m=argv[cur_arg++];
          if (flags&PRTF_COMMA) {
            comma_fmt_cnt=comma_cnt=4;
            do {
              tmp_buf[k]= m&15 +'0';
              if (tmp_buf[k]>'9') tmp_buf[k]+='a'-0x3A;
              k++;
              m>>=4;
              if (!m) break;
              if (!--comma_cnt) {
                tmp_buf[k++]=',';
                comma_cnt=4;
              }
            } while (k<TMP_BUF_LEN-SLOP);
            goto sp_out_comma_num;
          } else {
            do {
              tmp_buf[k]= m&15 +'0';
              if (tmp_buf[k]>'9') tmp_buf[k]+='a'-0x3A;
              k++;
              m>>=4;
            } while (m && k<TMP_BUF_LEN-SLOP);
            goto sp_out_num;
          }
        case 'b':
        case 'B':
          if (cur_arg>=argc)
            throw('StrPrint');
          m=argv[cur_arg++];
          if (flags&PRTF_COMMA) {
            comma_fmt_cnt=comma_cnt=4;
            do {
              tmp_buf[k++]= m&1 +'0';
              m>>=1;
              if (!m) break;
              if (!--comma_cnt) {
                tmp_buf[k++]=',';
                comma_cnt=4;
              }
            } while (k<TMP_BUF_LEN-SLOP);
            goto sp_out_comma_num;
          } else {
            do {
              tmp_buf[k++]= m&1 +'0';
              m>>=1;
            } while (m && k<TMP_BUF_LEN-SLOP);
            goto sp_out_num;
          }
        case '%':
          SPutChar(_dst,'%',_buf);
          break;
      }
    } else
      SPutChar(_dst,ch,_buf);
  }
  SPutChar(_dst,0,_buf);
  return buf;
}

U8 *StrPrint(U8 *dst,U8 *fmt,...)
