  I64 i;
  Bool res=FALSE;
  "Port:%04X,%04XUnit:%02X",bd->base0,bd->base1,bd->unit;
  if (ATAProbe(bd->base0,bd->base1,bd->unit)==BDT_ATAPI) {
    "ATAPI";
    if (ATAPIStartStop(bd,tS+5.0,TRUE)) {
      "Started";
      for (i=0;i<2;i++) {//Retry
        if (ATAPIReadBlks2(bd,tS+7.0,img,sys_boot_blk,1,FALSE)) {
