        res=RedSeaFilesDel(dirc->dv,Fs->cur_dir,dirc->mask,
              0,del_dir,print_msg);
        break;
      case FSt_FAT32:
        res=FAT32FilesDel(dirc->dv,Fs->cur_dir,dirc->mask,
              0,del_dir,print_msg);
        break;
      default:
        PrintErr("File System Not Supported\n");
    }
    DirContextDel(dirc);
  }
  return res;
}
